// 題庫資料 - 各科目範例題目
const QUESTION_BANK = {

  chinese: [
    { id:"c1", difficulty:"easy", text:"下列哪個成語使用正確？", options:["他這次考試名落孫山，真是太倒楣了","這道菜色香味俱全，令人垂涎三尺","他首當其衝，成為第一名","她不厭其煩地向上司拍馬屁"], answer:1, explanation:"「垂涎三尺」比喻看到好東西非常貪饞渴望，用來形容食物誘人是正確用法。" },
    { id:"c2", difficulty:"easy", text:"「春蠶到死絲方盡，蠟炬成灰淚始乾」出自哪位詩人？", options:["杜甫","李白","李商隱","白居易"], answer:2, explanation:"此句出自唐代詩人李商隱的《無題》，以春蠶吐絲、蠟燭燃淚比喻深情。" },
    { id:"c3", difficulty:"medium", text:"下列文句中，「之」字的用法與「水陸草木之花」相同的是？", options:["何陋之有","予獨愛蓮之出淤泥而不染","無絲竹之亂耳","菊，花之隱逸者也"], answer:3, explanation:"「水陸草木之花」與「菊，花之隱逸者也」中的「之」皆為結構助詞，表示修飾關係（的）。" },
    { id:"c4", difficulty:"medium", text:"《儒林外史》的作者是？", options:["曹雪芹","吳承恩","吳敬梓","羅貫中"], answer:2, explanation:"《儒林外史》是清代吳敬梓所著的長篇小說，以諷刺科舉制度為主題。" },
    { id:"c5", difficulty:"hard", text:"「信言不美，美言不信；善者不辯，辯者不善」出自哪部典籍？", options:["《論語》","《孟子》","《道德經》","《莊子》"], answer:2, explanation:"此句出自老子的《道德經》第八十一章，是全書的結尾，強調真實質樸的重要性。" },
    { id:"c6", difficulty:"easy", text:"下列「」中的字，讀音前後相同的是？", options:["「屏」息以待／孔雀「屏」風","「數」典忘祖／「數」罟不入洿池","自怨自「艾」／期期「艾艾」","「解」送犯人／押「解」"], answer:2, explanation:"「自怨自艾」與「期期艾艾」中的「艾」皆讀作ㄞˋ。A前者讀ㄅㄧㄥˇ、後者讀ㄆㄧㄥˊ；B前者讀ㄕㄨˇ、後者讀ㄘㄨˋ；D前者讀ㄐㄧㄝˋ、後者讀ㄐㄧㄝˋ以外的語音辨析需依詞義判斷，故C最明確。" },
    { id:"c7", difficulty:"easy", text:"下列各句中的成語，使用最恰當的是？", options:["這篇文章內容空洞，卻寫得天花亂墜，真是言之有物","他平日默默努力，這次比賽果然一鳴驚人，獲得冠軍","面對老師的批評，他總是首當其衝，從不願意承認錯誤","這家餐廳的菜色索然無味，讓大家食指大動"], answer:1, explanation:"「一鳴驚人」比喻平時默默無聞，一旦表現便令人驚訝，符合題意。A「言之有物」指說話或文章有實際內容，與「內容空洞」矛盾；C「首當其衝」指最先受到攻擊或遭遇災難，並非指承擔批評；D「食指大動」形容將有美味可吃，與「索然無味」矛盾。" },
    { id:"c8", difficulty:"medium", text:"「且夫天地之間，物各有主，苟非吾之所有，雖一毫而莫取。」下列對這段文字的理解，最恰當的是？", options:["主張天地萬物皆為人所共有，因此可以自由取用","強調做人應知足，不應貪取不屬於自己的事物","認為只要物品價值微小，就可以任意取得","主張人應積極追求財富，以免一無所有"], answer:1, explanation:"這段文字出自蘇軾〈赤壁賦〉，意思是天地萬物各有其歸屬，如果不是自己應得或擁有的，即使極其微小也不應取用，表現出知足自守、不貪非分之物的態度。" },
    { id:"c9", difficulty:"medium", text:"下列關於古典文學作品的敘述，何者正確？", options:["《史記》是由司馬光主持編纂的編年體史書","《出師表》是諸葛亮寫給劉備，表達北伐決心的文章","《桃花源記》透過桃花源的描寫，寄託作者對理想社會的嚮往","《岳陽樓記》是杜甫登樓後所作，用以描寫洞庭湖景色"], answer:2, explanation:"《桃花源記》作者陶淵明，藉由與世隔絕、人人安居樂業的桃花源，寄託對沒有戰亂、人民安定的理想社會之嚮往。A《史記》為司馬遷所著的紀傳體史書；B《出師表》寫給後主劉禪；D《岳陽樓記》作者為范仲淹。" },
    { id:"c10", difficulty:"hard", text:"閱讀下文：「古之學者為己，今之學者為人。君子之學也，以美其身；小人之學也，以為禽犢。」下列解釋最符合本文旨意的是？", options:["古代學者重視學問本身，現代學者則完全不需要學習","君子求學是為了修養自身，小人求學則容易流於炫耀或取悅他人","君子學習是為了獲得名利，小人學習則是為了提升道德","古人認為學習毫無實際用途，因此主張只重視個人品德"], answer:1, explanation:"這段話出自《荀子》，「為己」是為了自身修養與完善人格，「為人」則偏向為了在人前表現、博取名聲。後文以君子與小人對比，指出真正的學習應落實於自身品德修養，而不是只追求外在的名聲與利益。" },
    { id:"c11", difficulty:"medium", text:"下列文句「」內的字，讀音完全相同的選項是？", options:["功虧一「匱」／「匱」乏／「聵」聾發聵","「滄」海桑田／「愴」然涕下／寒「匶」","趨之若「鶩」／「鶩」遠務實／馳「騁」","揠苗「助」長／「詛」咒／「組」織"], answer:0, explanation:"(A)均讀作ㄍㄨㄟˋ。(B)ㄘㄤ／ㄔㄨㄤˋ／ㄐㄧㄡˋ，三字讀音不同。(C)ㄨˋ／ㄨˋ／ㄔㄥˇ，第三字不同。(D)ㄓㄨˋ／ㄗㄨˇ／ㄗㄨˇ，第一字不同。" },
    { id:"c12", difficulty:"medium", text:"下列文句「」內成語使用最恰當的選項是？", options:["這部小說情節「無懈可擊」，讀者一眼就能看出邏輯上的漏洞","兩家公司在市場上競爭多年，如今終於「破鏡重圓」，達成合作協議","面對經濟不景氣，企業更應該「未雨綢繆」，提早進行轉型與風險規劃","他的講稿寫得「不刊之論」，隨處可見語病與文理不通之處"], answer:2, explanation:"(A)「無懈可擊」指十分嚴密，沒有破綻可尋，與後文「漏洞」矛盾。(B)「破鏡重圓」多指夫妻離散後重新團聚，不宜用於公司合作。(C)「未雨綢繆」比喻事先做好準備，符合語境。(D)「不刊之論」指確鑿不移、不可磨滅的言論，非指語病多的文章。" },
    { id:"c13", difficulty:"medium", text:"關於《燭之武退秦師》的文意理解，下列敘述何者不正確？", options:["燭之武利用秦、晉兩國的利益矛盾，成功說服秦伯撤兵","燭之武向秦伯剖析「亡鄭」實質上是「缺秦以利晉」，切中秦伯利害心態","晉文公（重耳）在秦軍撤走後，怒發兵攻秦，顯示其性格暴躁","「微夫人之力不及此」展現晉文公克制理性、顧全大局的政治智慧"], answer:2, explanation:"(C)晉文公並未發兵攻秦，而是以「不仁、不知、不武」為由選擇撤兵，展現理智與大局觀，故(C)敘述不正確。" },
    { id:"c14", difficulty:"easy", text:"陶淵明《桃花源記》中「黃發垂髫，並怡然自樂」，句中「黃發」與「垂髫」分別代指何者？", options:["青年／幼童","老人／幼童","老人／婦女","青年／婦女"], answer:1, explanation:"「黃發」指老年人頭髮由白轉黃，借代老人；「垂髫」指古代兒童不簪髮、頭髮自然下垂，借代幼童。" },
    { id:"c15", difficulty:"medium", text:"關於近體詩（律詩與絕句）的格律規範，下列選項何者正確？", options:["律詩每首八句，其中頷聯（三四句）與頸聯（五六句）必須對仗","絕句每首四句，第一句與第三句必須押韻","近體詩字數嚴格固定，可隨意換韻","平仄只需注意每句最後一個字，句中平仄不加限制"], answer:0, explanation:"(A)正確，律詩中間兩聯（頷聯、頸聯）依法須對仗。(B)絕句偶數句（二、四句）必押韻，三句絕不押韻。(C)近體詩一韻到底，不可換韻。(D)近體詩句中平仄有嚴格規範（如「一三五不論，二四六分明」）。" },
    { id:"c16", difficulty:"medium", text:"下列文句「」內的詞語，何者不是借代修辭？", options:["何以解憂？唯有「杜康」","巾幗不讓「鬚眉」","臣本「布衣」，躬耕於南陽","白髮三千丈，緣愁似箇長"], answer:3, explanation:"(A)「杜康」借代酒。(B)「鬚眉」借代男子。(C)「布衣」借代平民。(D)「白髮三千丈」為誇飾修辭，非借代。" },
    { id:"c17", difficulty:"medium", text:"諸葛亮《出師表》中「親賢臣，遠小人，此先漢所以興隆也；親小人，遠賢臣，此後漢所以傾頹也」，主要運用了何種寫作手法？", options:["順敘與倒敘結合","正反對比說明","借景抒情","虛實相生"], answer:1, explanation:"以先漢「親賢遠小」興隆與後漢「親小遠賢」傾頹進行正反強烈對比，切諫後主劉禪應親賢遠佞。" },
    { id:"c18", difficulty:"easy", text:"「你站立的地方／正是你的中國／你光明／中國便不再黑暗」，這幾行詩句傳達的核心概念最接近下列何者？", options:["命運掌握在天意手中","個人的自主覺醒與社會責任","歷史潮流不可逆轉","隱居避世以求心靈平靜"], answer:1, explanation:"詩句強調個體行動（你光明）能改變整體環境（國家不再黑暗），凸顯個體的責任與主動性。" },
    { id:"c19", difficulty:"medium", text:"關於中國歷代散文發展，下列敘述何者正確？", options:["唐代韓愈、柳宗元倡導「古文運動」，主張恢復漢代以前質樸有物之散文","宋代駢文達到鼎盛，完全取代了唐代古文","明代公安派主張「文以載道」，強調格律嚴謹","清代桐城派主張「獨抒性靈，不拘格套」"], answer:0, explanation:"(A)正確，唐代古文運動反對六朝以來的浮華駢文，主張恢復先秦兩漢質樸實用的散文。(B)宋代古文成為主流（如宋代六大家）。(C)明代公安派主張「獨抒性靈，不拘格套」。(D)「獨抒性靈」為公安派主張，桐城派講求「義理、考據、文章」。" },
    { id:"c20", difficulty:"medium", text:"韓愈《師說》中「聖人無常師」，下列何者最能作為此觀點的佐證？", options:["孔子師郯子、長弘、師襄、老聃","師者，所以傳道受業解惑也","吾師道也，夫庸知其年之先後於吾乎","位卑則足羞，官盛則近諛"], answer:0, explanation:"韓愈舉孔子曾向郯子、長弘、師襄、老聃等人請教為例，證明「聖人無常師，學無常師」的道理。" },
    { id:"c21", difficulty:"easy", text:"子曰：「三人行，必有我師焉。擇其善者而從之，其不善者而改之。」這段話強調的學習態度是？", options:["擇鄰而處","隨時隨地皆可虛心學習與自我反省","專精於單一領域的學習","應只向社會地位高的人請教"], answer:1, explanation:"無論他人優缺點均可作為自己的鏡子（善者從之，不善者改之），強調廣泛汲取與自我審視的態度。" },
    { id:"c22", difficulty:"hard", text:"下列文句「」內的字，何者屬於「名詞轉動詞」（轉品）的用法？", options:["驢不勝怒，「蹄」之","稍稍「桑食」之","猛浪「若奔」","赤子「之心」"], answer:0, explanation:"(A)「蹄」本為名詞（蹄子），在此轉為動詞，指「用腳蹄踢」。(B)「桑」作修飾語，為名詞作副詞。(C)「奔」為動詞作名詞（奔跑的駿馬）。(D)「心」仍為名詞。" },
    { id:"c23", difficulty:"easy", text:"閱讀下文：「生命不是一場獲得，而是一場過程。我們在路途上記錄風景，而不是在終點計算行李。」這段話的核心旨意是？", options:["應重視結果而非過程","體驗與歷程的價值高於物質累積與結果","出外旅遊應減少行李負擔","人生苦短應及時行樂"], answer:1, explanation:"文中以「過程與風景」對比「終點與行李」，強調人生的重點在於活在當下的體驗與成長，而非物質或名利的終極結算。" },
    { id:"c24", difficulty:"medium", text:"蘇軾《赤壁賦》中「寄蜉蝣於天地，渺滄海之一粟」，主要表達何種感慨？", options:["政治失意的無奈與憤懣","人生短暫與個體微小的悲傷","讚嘆自然景觀的壯麗","批判歷史人物的功過"], answer:1, explanation:"「蜉蝣」喻生命短暫，「滄海一粟」喻個體渺小，表達對人生有限與天地無窮的深沉悲慨。" },
    { id:"c25", difficulty:"medium", text:"下列關於古代年齡代稱的排序，由小到大排列正確的選項是？（甲：弱冠　乙：束髮　丙：花甲　丁：及笄）", options:["丁→乙→甲→丙","乙→丁→甲→丙","丁→甲→乙→丙","乙→甲→丁→丙"], answer:0, explanation:"丁及笄（女子15歲）→乙束髮（男子15歲）→甲弱冠（男子20歲）→丙花甲（60歲），正確順序為丁→乙→甲→丙。" },
    { id:"c26", difficulty:"medium", text:"下列文句何者沒有語病？", options:["經過醫療團隊的全力搶救，終於使病患轉危為安","這位選手能否在奧運奪牌，關鍵在於他平時是否進行刻苦的訓練","讀書會上，大家圍繞著未來發展趨勢展開了熱烈的討論","為了防止這類安全事故不再發生，學校加強了校園巡查"], answer:2, explanation:"(A)缺少主詞（「經過...使...」導致主詞隱沒）。(B)兩面對一面邏輯不對稱。(C)正確，語法通順無語病。(D)否定不當，「防止...不再發生」邏輯相反，應改為「防止這類事故再次發生」。" },
    { id:"c27", difficulty:"medium", text:"歸有光《項脊軒志》中，作者藉由何種物件的變遷來貫穿項脊軒的盛衰與親人的離合？", options:["庭中枇杷樹","軒中書籍與牆壁修繕","闌楯與籬笆的設置與拆除","東犬西吠的場景"], answer:2, explanation:"文中寫大家庭分居後「內外多置小門，牆往往而是」，東犬西吠、客逾庖而宴，透過籬笆、牆垣等空間隔斷反映家族衰落與疏離。" },
    { id:"c28", difficulty:"medium", text:"關於中國古典四大名著的敘述，下列何者正確？", options:["《水滸傳》是中國最早的章回小說，以官逼民反為主題","《三國演義》為世說新語改編，充滿志人小說色彩","《西遊記》為神魔小說，全書僅描寫降妖伏魔，無隱喻色彩","《紅樓夢》以賈、史、王、薛四大家族為背景，為傑出的章回寫實小說"], answer:3, explanation:"(A)最早的章回小說一般公認為《三國演義》。(B)《三國演義》取材自《三國志》與民間傳說，非《世說新語》。(C)《西遊記》具深刻的情感與宗教、社會隱喻。(D)正確。" },
    { id:"c29", difficulty:"easy", text:"「AI 生成技術的爆發，讓創作的邊界變得模糊。當演算法能在幾秒內畫出一幅精美的畫作，人類創作者的獨特性不再體現於『技術的熟練』，而體現於『思想的深度與審美的批判力』。」根據上文，作者認為現代創作者最關鍵的價值在於？", options:["提升操作 AI 工具的熟練度","追求繪畫細節的精緻程度","培養深刻的思想與審美批判力","完全放棄傳統創作方式"], answer:2, explanation:"文章明確指出「人類創作者的獨特性不再體現於技術熟練，而體現於思想的深度與審美的批判力」。" },
    { id:"c30", difficulty:"medium", text:"《禮記・大同與小康》中關於「大同」與「小康」社會的比較，下列何者正確？", options:["大同社會「大道既隱」，小康社會「大道之行也」","大同社會「天下為公」，小康社會「天下為家」","大同社會重視「禮義以為紀」，小康社會「選賢與能」","大同社會與小康社會皆以「各親其親，各子其子」為基礎"], answer:1, explanation:"(A)大同為「大道之行」，小康為「大道既隱」，選項敘述相反。(B)正確，大同天下為公，小康天下為家。(C)「選賢與能」是大同，「禮義以為紀」是小康，選項顛倒。(D)「各親其親，各子其子」是小康社會的特徵。" },
    { id:"c31", difficulty:"medium", text:"下列詩句何者運用了「映襯」修辭？", options:["朱門酒肉臭，路有凍死骨","飛流直下三千尺，疑是銀河落九天","泉聲咽危石，日色冷青松","綠樹村邊合，青山郭外斜"], answer:0, explanation:"(A)以富貴人家的「酒肉臭」強烈對比窮人的「凍死骨」，為鮮明的映襯對比。(B)誇飾。(C)轉化／對偶。(D)對偶。" },
    { id:"c32", difficulty:"hard", text:"若有一副對聯，上聯為「綠竹半含南浦雨」，下列何者最適合作為下聯？", options:["春風又綠江南岸","紅葉盡醉西山楓","紅桃平行西嶺雲","晴雪初融北嶺梅"], answer:2, explanation:"「綠竹」對「紅桃」（顏色+植物）；「半含」對「平行」（副詞+動詞）；「南浦雨」對「西嶺雲」（方位+地點+自然景物），平仄相對，對仗最工。" },
    { id:"c33", difficulty:"medium", text:"袁宏道《晚遊六橋待月記》中「西湖最勝，為春為月。一日之計，為朝煙，為夕嵐」，這段文字主要展現的審美觀是？", options:["喜好熱鬧喧囂的節慶氛圍","偏好自然變化中的幽微奇景與避開人潮之美","著重於西湖歷史典故的考證","感嘆時光飛逝，應珍惜韶華"], answer:1, explanation:"袁宏道獨具慧眼，認為西湖最美在於春景、月夜、早晨山煙與傍晚山嵐，展現公安派追求獨特自然審美的品味。" },
    { id:"c34", difficulty:"medium", text:"下列文句「」內的詞語，古今意思相同的選項是？", options:["沛公奉宔「約為婚姻」","烈士暮年，壯心「不已」","葉徒相似，其實「味不同」","「率妻子」邑人，來此絕境"], answer:1, explanation:"(A)古義指結為兒女親家；今義指結婚的合法關係。(B)古今皆指「不停止、不停息」，古今義相同。(C)古義為「它的果實」；今義為轉折連詞「實際上」。(D)古義指妻子與兒女；今義僅指男性的配偶。" },
    { id:"c35", difficulty:"hard", text:"「用鯨魚的體溫／丈量太平洋的深度／用火山的噴發／紀錄島嶼的誕生」，這首詩的意象風格最可能屬於下列哪一位台灣海洋文學作家／詩人？", options:["夏宇","廖鴻基","余光中","楊牧"], answer:1, explanation:"詩句充滿海洋、島嶼與自然鯨豚意象，與長期關注海洋生態與鯨豚的海洋文學作家廖鴻基風格最為符合。" },
    { id:"c36", difficulty:"medium", text:"荀子《勸學》中「青，取之於藍，而青於藍；冰，水為之，而寒於水」，旨在說明何種道理？", options:["環境對人的性格有決定性影響","人經過後天的學習與修養，可以超越原本的資質並有所提升","後輩的成就必定無法超越前人","萬物皆在不斷變化循環之中"], answer:1, explanation:"以藍草提煉出更藍的青色、水凝結成比水更冷的冰為喻，強調學習能使人改變質性、提升能力。" },
    { id:"c37", difficulty:"medium", text:"下列著作與其體裁對應完全正確的選項是？", options:["《史記》——紀傳體通史","《資治通鑑》——紀傳體斷代史","《戰國策》——國別體編年史","《漢書》——編年體斷代史"], answer:0, explanation:"(A)正確，《史記》為司馬遷所著，是中國第一部紀傳體通史。(B)《資治通鑑》為編年體通史。(C)《戰國策》為國別體史書（非編年）。(D)《漢書》為紀傳體斷代史。" },
    { id:"c38", difficulty:"easy", text:"「當所有人都朝著同一個方向奔跑時，你停下來思考，本身就是一種勇敢；但若你只是為了與眾不同而向後跑，那叫盲從的反向。」根據這段話，作者最認同下列哪一種行為？", options:["永遠與大眾保持相同的行動方向","為了展現個性，故意與大眾作對","具備獨立思考能力，不盲從跟風也不刻意反叛","遇到困難時選擇放棄並停在原地"], answer:2, explanation:"文中既否定盲目跟風（朝同方向奔跑），也否定為了反對而反對（盲從的反向），提倡獨立思考的理性態度。" },
    { id:"c39", difficulty:"medium", text:"李斯《諫逐客書》中「泰山不讓土壤，故能成其大；河海不擇細流，故能就其深」，主要用來強調何種治國理念？", options:["嚴刑峻法以安邦定國","廣納人才與包容萬物才能使國家強大","重農抑商以積聚國家財富","發展武力以併吞六國"], answer:1, explanation:"以泰山不排斥土壤、河海不挑剔細流為喻，勸諫秦王應廣納天下客卿與人才，不應實施逐客令。" },
    { id:"c40", difficulty:"easy", text:"閱讀下文：「古人寫文章講究『留白』，如水墨畫中的空白處，非無物也，乃靈氣流動之所。現代人說話寫作恨不得把字填滿，深怕留下一絲縫隙讓讀者誤解，結果反而失去了想像的餘韻。」作者認為現代寫作缺乏「餘韻」的主因為何？", options:["詞彙量不足導致表達不清","過度追求表達精確完整，未給讀者留出想像空間","缺乏對水墨畫藝術的深刻理解","閱讀量減少導致寫作能力退化"], answer:1, explanation:"文中指出現代人「恨不得把字填滿，深怕留下縫隙」，導致缺乏古人「留白」帶來的想像空間與餘韻。" }
  ],

  english: [
    { id:"e1", difficulty:"easy", text:"Choose the correct word: She has been working here ___ three years.", options:["since","for","during","by"], answer:1, explanation:"\"for\" is used with a duration of time (three years). \"since\" is used with a point in time." },
    { id:"e2", difficulty:"easy", text:"Which sentence is grammatically correct?", options:["She don't like coffee","He don't want to go","They doesn't know","I don't understand"], answer:3, explanation:"\"I don't understand\" is correct. With 'I', we use 'do not (don't)'." },
    { id:"e3", difficulty:"medium", text:"The word \"benevolent\" most closely means:", options:["harmful","well-meaning and kindly","indifferent","aggressive"], answer:1, explanation:"\"Benevolent\" means well-meaning and kindly, often used to describe a kind, charitable person." },
    { id:"e4", difficulty:"medium", text:"Complete the sentence: Had she known about the meeting, she ___ attended.", options:["will have","would have","would","will"], answer:1, explanation:"This is a third conditional (hypothetical past). The structure is: Had + subject + past participle, subject + would have + past participle." },
    { id:"e5", difficulty:"hard", text:"Which of the following correctly uses the subjunctive mood?", options:["I suggest that he goes home","It is important that she is on time","The doctor recommends that the patient rest","He insists that she will apologize"], answer:2, explanation:"In the subjunctive mood, we use the base form of the verb. \"...that the patient rest\" (not rests) is the correct subjunctive form." },

    // ===== 詞彙題 (Q1–Q10) =====
    { id:"e6", difficulty:"medium", text:"The government launched a public campaign to ______ awareness about the importance of mental health among teenagers.", options:["elevate","raise","inflate","promote"], answer:1, explanation:"固定搭配 raise awareness 意為「提升意識/關注度」。(A) elevate 較常用於地位或高度；(C) inflate 指膨脹/誇大；(D) promote 指促進、晉升。" },
    { id:"e7", difficulty:"medium", text:"After hours of intense negotiation, the two diplomatic teams finally reached a ______ agreement on the border dispute.", options:["mutual","passive","flexible","severe"], answer:0, explanation:"reach a mutual agreement 意為「達成互相/雙方共同的協議」，符合語境。(B) 被動的；(C) 靈活的；(D) 嚴峻的。" },
    { id:"e8", difficulty:"easy", text:"The newly opened art gallery features a ______ collection of modern sculptures and classical oil paintings.", options:["hostile","diverse","reluctant","superficial"], answer:1, explanation:"diverse 意為「多樣的、各式各樣的」，最符合同時展示現代雕塑與古典油畫的語境。(A) 敵意的；(C) 勉強的；(D) 膚淺的。" },
    { id:"e9", difficulty:"easy", text:"Dr. Lin's innovative technique in eye surgery has significantly reduced the recovery time for patients with ______.", options:["cataracts","monuments","intervals","standardizations"], answer:0, explanation:"cataracts（白內障）是常見的眼科疾病，符合「眼科手術技術」的語境。(B) 紀念碑；(C) 間隔；(D) 標準化。" },
    { id:"e10", difficulty:"medium", text:"Severe droughts in the region have led to a critical ______ of clean drinking water, forcing local authorities to enforce rationing.", options:["surplus","clearance","shortage","storage"], answer:2, explanation:"shortage 意為「短缺、不足」，嚴重乾旱導致飲用水嚴重短缺。(A) 剩餘；(B) 清除/出清；(D) 儲存。" },
    { id:"e11", difficulty:"medium", text:"The tech startup received substantial financial backing after demonstrating a working ______ of their renewable energy device.", options:["prototype","heritage","obstacle","paradox"], answer:0, explanation:"prototype 意為「原型、雛形」，新創公司展示可運作的裝置原型後獲得資金。(B) 遺產；(C) 障礙；(D) 矛盾。" },
    { id:"e12", difficulty:"easy", text:"Heavy traffic during peak hours often makes commuting to the city center an extremely ______ experience for drivers.", options:["affectionate","frustrating","moderate","preliminary"], answer:1, explanation:"frustrating 意為「令人沮喪/惱怒的」，尖峰時刻塞車通勤是極為令人氣餒的體驗。(A) 深情的；(C) 適度的；(D) 初步的。" },
    { id:"e13", difficulty:"medium", text:"Modern smartphones possess enough computing power to ______ complex graphics and process large datasets seamlessly.", options:["render","inspect","yield","dismiss"], answer:0, explanation:"render 在資訊領域指「渲染/呈現圖形」，是固定用法 render graphics。(B) 檢查；(C) 產出；(D) 駁回。" },
    { id:"e14", difficulty:"medium", text:"The local community expressed strong opposition to the construction project, fearing it would ______ damage the natural habitat.", options:["temporarily","irretrievably","mutually","shallowly"], answer:1, explanation:"irretrievably 意為「無法挽回地、不可復原地」，擔心建設案將無可彌補地破壞自然棲地。(A) 暫時地；(C) 相互地；(D) 膚淺地。" },
    { id:"e15", difficulty:"hard", text:"Scientists are developing new synthetic materials that can ______ natural spider silk in terms of tensile strength and elasticity.", options:["imitate","deteriorate","eliminate","accommodate"], answer:0, explanation:"imitate 意為「模仿、仿製」，指新型合成材料能仿製蜘蛛絲的抗拉強度與彈性。(B) 劣化；(C) 消除；(D) 容納。" },
  ],

  math: [
    { id:"m1", difficulty:"easy", text:"若 f(x) = 2x + 3，則 f(4) = ？", options:["8","10","11","12"], answer:2, explanation:"f(4) = 2×4 + 3 = 8 + 3 = 11" },
    { id:"m2", difficulty:"easy", text:"一個圓的半徑為 5，其面積為？（π ≈ 3.14）", options:["15.7","31.4","78.5","157"], answer:2, explanation:"圓面積 = πr² = 3.14 × 5² = 3.14 × 25 = 78.5" },
    { id:"m3", difficulty:"medium", text:"解方程式 x² - 5x + 6 = 0，x 的值為？", options:["x=1 或 x=6","x=2 或 x=3","x=-2 或 x=-3","x=1 或 x=5"], answer:1, explanation:"x² - 5x + 6 = (x-2)(x-3) = 0，所以 x = 2 或 x = 3" },
    { id:"m4", difficulty:"medium", text:"從 1 到 100 的整數中，能被 3 整除的數有幾個？", options:["30","32","33","34"], answer:2, explanation:"能被 3 整除：3, 6, 9, ..., 99。共有 99÷3 = 33 個。" },
    { id:"m5", difficulty:"hard", text:"若 sin θ = 3/5（0° < θ < 90°），則 tan θ = ？", options:["3/4","4/3","3/5","4/5"], answer:0, explanation:"由 sin θ = 3/5，利用畢氏定理：cos θ = 4/5，所以 tan θ = sin θ/cos θ = (3/5)/(4/5) = 3/4" },
  ],

  physics: [
    { id:"p1", difficulty:"easy", text:"牛頓第二運動定律的公式為？", options:["F = mv","F = ma","F = m/a","F = v/t"], answer:1, explanation:"牛頓第二定律：F = ma，即力等於質量乘以加速度。" },
    { id:"p2", difficulty:"easy", text:"光在真空中的速度約為？", options:["3×10⁶ m/s","3×10⁸ m/s","3×10¹⁰ m/s","3×10⁴ m/s"], answer:1, explanation:"光在真空中的速度約為 3×10⁸ m/s（30萬公里/秒）。" },
    { id:"p3", difficulty:"medium", text:"一物體質量 2kg 從靜止出發，受到 10N 的合力作用，5秒後速度為？", options:["10 m/s","20 m/s","25 m/s","50 m/s"], answer:2, explanation:"加速度 a = F/m = 10/2 = 5 m/s²，v = at = 5×5 = 25 m/s" },
    { id:"p4", difficulty:"medium", text:"電阻 R = 10Ω，電壓 V = 20V，電流 I = ？", options:["0.5 A","2 A","200 A","0.2 A"], answer:1, explanation:"依歐姆定律 I = V/R = 20/10 = 2 A" },
    { id:"p5", difficulty:"hard", text:"質量 m 的物體在高度 h 處的重力位能（g 為重力加速度）為？", options:["mgh²","½mgh","mgh","mg/h"], answer:2, explanation:"重力位能 Ep = mgh，其中 m 為質量，g 為重力加速度，h 為高度。" },
  ],

  chemistry: [
    { id:"ch1", difficulty:"easy", text:"水的化學式為？", options:["H₂O₂","HO","H₂O","H₃O"], answer:2, explanation:"水（Water）的化學式為 H₂O，由兩個氫原子和一個氧原子組成。" },
    { id:"ch2", difficulty:"easy", text:"元素週期表中原子序為 1 的元素是？", options:["氦（He）","氧（O）","碳（C）","氫（H）"], answer:3, explanation:"氫（H）的原子序為 1，是週期表中最輕的元素。" },
    { id:"ch3", difficulty:"medium", text:"pH = 7 的溶液為？", options:["強酸","弱酸","中性","鹼性"], answer:2, explanation:"pH = 7 表示中性溶液，pH < 7 為酸性，pH > 7 為鹼性。" },
    { id:"ch4", difficulty:"medium", text:"下列哪個是氧化反應的正確描述？", options:["得到電子","失去氫","失去氧","失去電子"], answer:3, explanation:"氧化反應定義：失去電子（或失去氫、得到氧）。還原反應相反。" },
    { id:"ch5", difficulty:"hard", text:"乙醇（C₂H₅OH）完全燃燒的產物為？", options:["CO 和 H₂O","CO₂ 和 H₂","CO₂ 和 H₂O","C 和 H₂O"], answer:2, explanation:"乙醇完全燃燒：C₂H₅OH + 3O₂ → 2CO₂ + 3H₂O，產物為二氧化碳和水。" },
  ],

  biology: [
    { id:"b1", difficulty:"easy", text:"細胞的能量工廠是？", options:["細胞核","細胞膜","粒線體","葉綠體"], answer:2, explanation:"粒線體（Mitochondria）是細胞進行有氧呼吸、產生 ATP 的場所，被稱為細胞的能量工廠。" },
    { id:"b2", difficulty:"easy", text:"光合作用的場所是？", options:["粒線體","核糖體","葉綠體","細胞核"], answer:2, explanation:"葉綠體是植物進行光合作用的場所，利用光能將 CO₂ 和 H₂O 合成有機物。" },
    { id:"b3", difficulty:"medium", text:"DNA 的雙螺旋結構由哪位科學家發現？", options:["孟德爾","達爾文","華生與克里克","巴斯德"], answer:2, explanation:"1953 年，詹姆斯·華生（Watson）和法蘭西斯·克里克（Crick）發現了 DNA 的雙螺旋結構。" },
    { id:"b4", difficulty:"medium", text:"人體血液中負責運輸氧氣的是？", options:["白血球","血小板","紅血球","血漿"], answer:2, explanation:"紅血球中含有血紅素（Hemoglobin），能與氧氣結合，負責在全身輸送氧氣。" },
    { id:"b5", difficulty:"hard", text:"下列哪個不是有性生殖的特徵？", options:["具有遺傳多樣性","需要兩個親本","後代與親本基因完全相同","能增加物種適應性"], answer:2, explanation:"有性生殖的後代遺傳了來自兩個親本的基因，具有遺傳多樣性，後代不會與親本基因完全相同。" },
  ],

  history: [
    { id:"h1", difficulty:"easy", text:"台灣在清朝時期，最早被設立為省份是哪一年？", options:["1683年","1895年","1885年","1860年"], answer:2, explanation:"1885年，清朝將台灣正式設立為行省，劉銘傳為首任巡撫。" },
    { id:"h2", difficulty:"easy", text:"馬關條約（1895年）主要將台灣割讓給哪個國家？", options:["英國","法國","日本","美國"], answer:2, explanation:"1895年甲午戰爭後，清朝與日本簽訂馬關條約，將台灣、澎湖割讓給日本。" },
    { id:"h3", difficulty:"medium", text:"法國大革命爆發於哪一年？", options:["1776年","1789年","1800年","1815年"], answer:1, explanation:"法國大革命爆發於1789年，是世界近代史上重要的民主革命事件。" },
    { id:"h4", difficulty:"medium", text:"第二次世界大戰結束的年份是？", options:["1943年","1944年","1945年","1946年"], answer:2, explanation:"二戰於1945年結束，歐洲戰場於5月8日結束（V-E Day），太平洋戰場於9月2日結束（V-J Day）。" },
    { id:"h5", difficulty:"hard", text:"下列何者是工業革命最早發生的國家？", options:["法國","德國","美國","英國"], answer:3, explanation:"工業革命（18世紀中葉）最早發生在英國，以蒸汽機的廣泛應用為標誌，逐漸擴展至歐洲及世界各地。" },

    // ===== 模擬學測歷史（上）單選題 Q1–Q10 =====
    { id:"h6",  difficulty:"medium", text:"某份歷史文件寫道：「島上居民若不願成為新政府之臣民，得於兩年內變賣產業離去，逾期未離去者視為新政府之國民。」這份文件最可能出自下列何者？", options:["1662年《鄭成功與荷蘭締結之和約》","1684年《福建省臺灣府設官治理詔書》","1895年《馬關條約》","1945年《開羅宣言》"], answer:2, explanation:"題幹提及「移交土地與管轄權」、「居民得於兩年內變賣產業離去（國籍選擇權）」，此為1895年中日《馬關條約》中關於臺灣割讓予日本及居民「國籍選擇期限」之規定。" },
    { id:"h7",  difficulty:"medium", text:"臺灣歷史上有一個時期，官府嚴格限制大陸移民渡臺，規定渡臺者不得攜帶家眷，導致臺灣社會出現「有唐山公，無唐山媽」的現象。請問此一政策主要實施於哪一個時期？", options:["荷治時期","鄭氏治臺時期","清領前期","日治時期"], answer:2, explanation:"清領前期為防範臺灣成為反清基地，實施「渡臺禁令」，嚴禁攜眷，導致臺灣漢人社會呈現男女比例失衡的「羅漢腳」社會現象。" },
    { id:"h8",  difficulty:"medium", text:"某個朝代廢除丞相制度，由皇帝親理國政，並設立內閣作為皇帝的秘書機構；同時在地方嚴格控管，實施海禁政策以防範海盜。請問這個朝代為何？", options:["唐朝","宋朝","明朝","清朝"], answer:2, explanation:"明太祖朱元璋廢除丞相、直轄六部，並設內閣；明代實施海禁以防範倭寇。" },
    { id:"h9",  difficulty:"medium", text:"日本幕府核發帶有紅色印章的官方許可證，允許商人合法前往東南亞及臺灣等地進行貿易，歷史上稱之為「朱印船貿易」。請問這是指日本的哪一個歷史時期？", options:["鎌倉幕府","室町幕府","江戶幕府（德川幕府）","明治政府"], answer:2, explanation:"16世紀末至17世紀初，江戶幕府（德川家康）發放「朱印狀」，允許朱印船至東南亞及臺灣（高砂）進行貿易。" },
    { id:"h10", difficulty:"easy",   text:"一位歐洲君主宣稱「朕即國家」，強調君權神授，並興建了奢華的凡爾賽宮以展現王權的鼎盛。請問這位君主是誰？", options:["英國國王查理一世","法國國王路易十四","俄國沙皇彼得大帝","普魯士國王腓特烈大帝"], answer:1, explanation:"法國國王路易十四為專制君主的代表，宣稱「朕即國家」，並興建凡爾賽宮。" },
    { id:"h11", difficulty:"easy",   text:"18世紀末爆發的某一場重大歷史事件，標榜「自由、平等、博愛」的口號，不僅推翻了封建專制王權，也深刻震撼了整個歐洲的政治秩序。請問這場事件為何？", options:["英國光榮革命","美國獨立戰爭","法國大革命","俄國十月革命"], answer:2, explanation:"1789年爆發的法國大革命，提出《人權宣言》，標榜自由、平等、博愛，衝擊歐洲封建體制。" },
    { id:"h12", difficulty:"medium", text:"臺灣在1920年代，某個組織發行《臺灣民報》，並透過舉辦講演會、電影巡迴等方式，向大眾啟蒙現代民主與文化思想。請問這個組織為何？", options:["臺灣民眾黨","臺灣文化協會","臺灣工友總聯盟","臺灣地方自治聯盟"], answer:1, explanation:"1921年林獻堂、蔣渭水等人成立「臺灣文化協會」，發行《臺灣民報》，透過講座與演劇進行文化啟蒙。" },
    { id:"h13", difficulty:"medium", text:"中國歷史上某次運動主張「師夷長技以制夷」，大量引進西方科技、建造軍艦、設立江南機器製造總局與京師同文館。請問這是指哪一個運動？", options:["洋務運動","戊戌變法","立憲運動","新文化運動"], answer:0, explanation:"清末洋務運動（自強運動）以「師夷長技以制夷」、「強兵富國」為口號，推動設廠造船與西式教育。" },
    { id:"h14", difficulty:"easy",   text:"第一次世界大戰爆發的導火線是1914年發生的「塞拉耶佛事件」。請問當時被刺殺的奧匈帝國皇儲，是在哪一個地區遇刺？", options:["伊比利半島","義大利半島","巴爾幹半島","斯堪地那維亞半島"], answer:2, explanation:"塞拉耶佛位於巴爾幹半島（波士尼亞），該區因民族與列強矛盾尖銳而被稱為「歐洲火藥庫」。" },
    { id:"h15", difficulty:"easy",   text:"1947年臺灣爆發了二二八事件，其爆發的直接導火線是查緝員查緝何種管制物品時，毆打女販並誤殺民眾所引發？", options:["鴉片","專賣私菸","稻米","糖"], answer:1, explanation:"1947年2月27日，專賣局查緝員於臺北市天馬茶房前查緝私菸，毆打女販林江邁並誤殺市民陳文溪，引發次日的二二八事件。" },

    // ===== 模擬學測歷史（下）單選題 Q16–Q22 =====
    { id:"h16", difficulty:"medium", text:"某時期的臺灣，出現了第一本由臺灣人自己撰寫的通史著作，同時也成立了第一個合法政黨，知識份子試圖透過議會設置請願運動爭取政治權利。請問這是哪一個時期的臺灣？", options:["鄭氏治臺時期","清領後期","日治時期","戰後初期"], answer:2, explanation:"連橫《臺灣通史》、臺灣民眾黨（第一合法政黨）與臺灣議會設置請願運動，均為1920–1930年代日治時期的重要歷史事件。" },
    { id:"h17", difficulty:"medium", text:"某位君主實施全面漢化政策，包括禁說胡語、改穿漢服、改用漢姓，並將首都從平城遷至洛陽。請問這是指哪一位君主的改革？", options:["秦始皇","漢武帝","北魏孝文帝","唐太宗"], answer:2, explanation:"北魏孝文帝推行鮮卑族的全面漢化改革（遷都洛陽、改漢姓、穿漢服、說漢語），以促進民族融合與鞏固統治。" },
    { id:"h18", difficulty:"medium", text:"17至18世紀的歐洲，思想家主張用「理性」批判傳統宗教迷信與專制王權，提出天賦人權、三權分立、主權在民等現代民主政治觀念。請問這場運動稱為？", options:["文藝復興","宗教改革","啟蒙運動","工業革命"], answer:2, explanation:"18世紀的啟蒙運動（Enlightenment）以理性為核心，反對君主專制與教會權威，提出現代民主憲政思想。" },
    { id:"h19", difficulty:"medium", text:"1950年代臺灣土地改革政策的實施先後順序為何？（甲：耕者有其田　乙：三七五減租　丙：公地放領）", options:["甲→乙→丙","乙→丙→甲","丙→乙→甲","乙→甲→丙"], answer:1, explanation:"戰後臺灣土地改革三部曲之順序為：1949年實施「三七五減租」→1951年實施「公地放領」→1953年實施「耕者有其田」。" },
    { id:"h20", difficulty:"easy",   text:"第一次世界大戰後召開的某場會議，會中簽署了《凡爾賽條約》，並根據美國總統威爾遜的「十四點原則」成立了國際聯盟。請問這場會議地點位於何處？", options:["倫敦","巴黎","華盛頓","維也納"], answer:1, explanation:"1919年一戰結束後召開巴黎和會，簽署《凡爾賽條約》並建立國際聯盟（League of Nations）。" },
    { id:"h21", difficulty:"medium", text:"魏晉南北朝時期，許多士大夫與知識份子喜好談論《老子》、《莊子》與《周易》，追求超脫世俗的哲學討論。這種風氣在歷史上稱之為？", options:["理學","心學","玄學","考據學"], answer:2, explanation:"魏晉時期政治動盪，名士避世尚空談，喜研讀《老子》、《莊子》、《周易》（合稱「三玄」），形成了玄學風氣。" },
    { id:"h22", difficulty:"easy",   text:"二次大戰期間，美、英、中三國領袖於1943年召開會議，並發表宣言，明確指出「日本所竊取於中國之領土，例如東北四省、臺灣、澎湖群島等，歸還中華民國」。請問這是哪一個宣言？", options:["《大西洋憲章》","《開羅宣言》","《雅爾達協定》","《波茨坦宣言》"], answer:1, explanation:"1943年蔣中正、羅斯福、邱吉爾召開開羅會議，會後發表的《開羅宣言》明確要求日本歸還東北、臺灣、澎湖。" },

    // ===== 模擬學測歷史（下）閱讀題單選 Q26, Q28, Q30 =====
    { id:"h23", difficulty:"medium", text:"1930年代，日本殖民政府要求臺灣人改用日本姓氏、禁止使用漢語、推行神道教信仰、鼓勵臺灣青年投身東亞戰場。請問日本殖民政府在1930年代後期於臺灣推行的這項重大政策名稱為何？", options:["內地延長主義","無方針主義","皇民化運動","渡臺禁令政策"], answer:2, explanation:"1937年中日戰爭全面爆發後，總督府在臺灣推動「皇民化運動」，試圖將臺灣人同化為忠君愛國的「日本皇民」。" },
    { id:"h24", difficulty:"medium", text:"日本殖民政府推行皇民化運動的主要政治與軍事目的為何？", options:["協助臺灣獨立建國","動員臺灣的人力與物力支援日本的對外侵略戰爭（太平洋戰爭）","促進臺日平等的政治權利分配","推動臺灣全盤西化"], answer:1, explanation:"皇民化運動的核心宗旨在於全面進行精神與物資動員，使臺灣人認同日本國家利益，進而投入對外侵略戰爭。" },
    { id:"h25", difficulty:"easy",   text:"皇民化運動終止於哪一個歷史事件發生之後？", options:["1937年七七事變","1941年珍珠港事變","1945年第二次世界大戰結束（日本無條件投降）","1947年二二八事件"], answer:2, explanation:"1945年8月日本宣布無條件投降、第二次世界大戰結束，日本對臺灣的殖民統治及皇民化運動隨之終止。" },
  ],

  geography: [
    { id:"g1", difficulty:"easy", text:"台灣最高峰是？", options:["雪山","合歡山","玉山","阿里山"], answer:2, explanation:"玉山（海拔3952公尺）是台灣及東北亞第一高峰，也是台灣五嶽之首。" },
    { id:"g2", difficulty:"easy", text:"台灣位於哪個氣候帶？", options:["溫帶","寒帶","熱帶與亞熱帶","沙漠氣候"], answer:2, explanation:"台灣北部屬亞熱帶，南部屬熱帶，北回歸線橫貫嘉義附近，為熱帶與亞熱帶氣候。" },
    { id:"g3", difficulty:"medium", text:"亞馬遜河主要流經哪個國家？", options:["阿根廷","秘魯","巴西","哥倫比亞"], answer:2, explanation:"亞馬遜河是世界最大的河流（以水量計算），約60%流域位於巴西境內。" },
    { id:"g4", difficulty:"medium", text:"下列哪個山脈是歐洲與亞洲的天然分界線之一？", options:["阿爾卑斯山","喜馬拉雅山","烏拉山","庇里牛斯山"], answer:2, explanation:"烏拉山（Ural Mountains）是歐洲與亞洲的傳統地理分界線之一，位於俄羅斯境內。" },
    { id:"g5", difficulty:"hard", text:"下列哪種農業生產方式最適合台灣西部平原？", options:["游牧業","刀耕火種","集約農業","粗放農業"], answer:2, explanation:"台灣西部平原（嘉南平原等）地狹人稠，適合集約農業（密集使用勞動力、資本和技術以提高單位產量）。" },

    // ===== 模擬學測地理（上）單選題 Q1–Q10 =====
    { id:"g6",  difficulty:"medium", text:"某農夫欲利用地理資訊系統（GIS）評估其果園的土地適宜性，他將「坡度」、「土壤酸鹼度」與「距道路距離」三種資料圖層進行疊加分析。請問此種將多個圖層進行交集或聯集運算的 GIS 分析功能稱為？", options:["視域分析","空間疊置分析","最短路徑分析","地表內插分析"], answer:1, explanation:"GIS 中將多個不同主題的圖層（如坡度、土壤、交通）進行交集、聯集或疊加運算，以進行綜合評估，稱為「空間疊置分析」（Overlay Analysis）。" },
    { id:"g7",  difficulty:"medium", text:"臺灣東北角的野柳以女王頭聞名，該地貌主要是受到哪兩種外力作用的共同影響而形成？", options:["冰河侵蝕與風力堆積","海蝕作用與風化作用","溶蝕作用與河流堆積","重力崩落與斷層作用"], answer:1, explanation:"野柳女王頭係由砂岩組成，因海水長期侵蝕（海蝕）加上風化作用（差別風化），使頸部逐漸變細而形成。" },
    { id:"g8",  difficulty:"easy",   text:"氣候圖中，若某地的最冷月均溫大於 18°C，且年降水量豐富、各月降水分配均勻，無明顯乾季，請問該地屬於下列哪一種氣候類型？", options:["熱帶雨林氣候","熱帶莽原氣候","地中海型氣候","溫帶海洋性氣候"], answer:0, explanation:"最冷月均溫 >18°C 為熱帶氣候；全年多雨且降水分配均勻、無乾季者，為熱帶雨林氣候。" },
    { id:"g9",  difficulty:"medium", text:"臺灣「櫻花鉤吻鮭」主要棲息於雪霸國家公園內的七家灣溪。請問七家灣溪屬於下列哪一條水系的上游支流？", options:["淡水河","濁水溪","大甲溪","秀姑巒溪"], answer:2, explanation:"七家灣溪位於臺中市和平區，為大甲溪上游的主要支流。" },
    { id:"g10", difficulty:"medium", text:"某種農業類型多分布於人口稠密、地狹人稠的地區，特色為單位面積投入大量勞動人力與肥料，以追求高單位面積產量，但勞動生產力較低。請問這是指下列哪一種農業類型？", options:["商業性穀物農業","水稻水田農業","放牧業","混合農業"], answer:1, explanation:"水稻水田農業主要分布於東亞、南亞及東南亞季風區，具有集約度高、單位面積產量高、勞力投入密集但勞動生產力較低的特徵。" },
    { id:"g11", difficulty:"medium", text:"許多跨國企業將生產製造過程拆解，分工交由不同國家或地區代工，以降低成本。請問這種將生產過程全球化的現象稱為？", options:["國際分工（全球生產鏈）","地方聚集經濟","工業集群化","進口替代"], answer:0, explanation:"跨國公司將產品設計、零組件製造、組裝等工序分工給全球成本最低或最有利的地區，此稱為全球生產鏈或國際分工。" },
    { id:"g12", difficulty:"medium", text:"歐洲地中海沿岸地區（如義大利南部、希臘）夏乾冬雨，夏季受哪一個氣壓帶或風帶控制，導致氣候炎熱乾燥？", options:["赤道低壓帶","副熱帶高壓帶","盛行西風帶","副極地低壓帶"], answer:1, explanation:"地中海型氣候夏季隨氣壓帶北移，受副熱帶高壓帶沉降氣流控制，氣候炎熱乾燥。" },
    { id:"g13", difficulty:"easy",   text:"臺灣都市化過程中，許多大都市邊緣農地逐漸被開發為住宅區或工業區，都市範圍不斷向外擴張與周邊城鎮連成一片。請問這種現象稱為？", options:["都市更新","都市擴張（蔓延）","逆都市化","都市衰退"], answer:1, explanation:"都市規模持續擴大，邊緣土地被開發並與周圍城鎮連成一氣，此現象稱為都市擴張（Urban Sprawl）或都市蔓延。" },
    { id:"g14", difficulty:"medium", text:"南美洲的亞馬遜盆地近年來遭到嚴重破壞，請問下列何者不是亞馬遜雨林大量砍伐的主要原因？", options:["開墾大豆農場與牧草地","商業採伐珍貴木材","開採礦產與興建公路","發展溫帶小麥栽培區"], answer:3, explanation:"亞馬遜盆地屬熱帶雨林氣候，並不適合發展溫帶小麥栽培。砍伐主因為畜牧（農場）、商業採伐、農地開墾與礦產開發。" },
    { id:"g15", difficulty:"medium", text:"日本位於環太平洋火山地震帶上，請問日本列島主要是由哪兩個板塊相互碰撞擠壓而形成？", options:["歐亞板塊與菲律賓海板塊（及太平洋板塊）","印澳板塊與非洲板塊","美洲板塊與南極洲板塊","非洲板塊與歐亞板塊"], answer:0, explanation:"日本列島位於歐亞板塊與太平洋板塊、菲律賓海板塊之隱沒帶上，形成島弧與海溝。" },

    // ===== 模擬學測地理（下）單選題 Q16–Q22 =====
    { id:"g16", difficulty:"hard",   text:"臺灣高山地區常見陡峭的地形，許多山脊呈現狹窄如刀刃般的脊線（如雪山聖稜線）。請問這種地形特色主要是受到下列哪一種外力作用的形塑？", options:["海蝕作用","冰河侵蝕作用","風力堆積作用","溶蝕作用"], answer:1, explanation:"臺灣海拔3,000公尺以上高山（如雪山、玉山）在冰河時期曾受冰河侵蝕作用，形成角峰、刃脊（刀刃狀脊線）及圈谷地形。" },
    { id:"g17", difficulty:"medium", text:"某國的年齡結構金字塔呈「上寬下窄」的倒金字塔型，幼年人口比例低於 14%，老年人口比例超過 20%。請問該國最可能面臨下列哪一種社會問題？", options:["幼兒托育機構嚴重不足","勞動力短缺與長期照護負擔加重","糧食短缺與居住空間嚴重不足","學齡兒童失學率飆高"], answer:1, explanation:"倒金字塔型人口結構代表少子化與超高齡化（老年人口>20%），會導致青壯年勞動力短缺、社會福利負擔及照護需求大增。" },
    { id:"g18", difficulty:"easy",   text:"東南亞的中南半島地區（如泰國、越南）主要屬於哪一種氣候類型，其降水主要受季風支配，呈現明顯的乾濕兩季？", options:["熱帶雨林氣候","熱帶季風氣候","地中海型氣候","溫帶海洋性氣候"], answer:1, explanation:"中南半島位處熱帶，受夏西南季風與冬東北季風影響，形成夏雨冬乾、乾濕分明的熱帶季風氣候。" },
    { id:"g19", difficulty:"medium", text:"某跨國連鎖速食品牌在進入印度市場時，將牛肉漢堡改為植物肉或雞肉，並推出咖哩風味餐點。請問這種跨國企業調整產品以適應當地文化與消費習慣的現象稱為？", options:["全球在地化（Glocalization）","全球均一化（Homogenization）","區域同質化","地方產業集聚"], answer:0, explanation:"跨國企業在進行全球化擴展時，針對當地文化、宗教與飲食習慣進行產品調整，此為「全球在地化」（Glocalization）的展現。" },
    { id:"g20", difficulty:"medium", text:"臺灣在 1970 年代推動「十大建設」，包括興建台中港與蘇澳港、縱貫鐵路電氣化、中山高速公路等。請問這些建設主要是為了解決當時哪種發展瓶頸？", options:["農業生產力不足","交通基礎設施不足與運輸瓶頸","高科技人才缺乏","環境污染過度嚴重"], answer:1, explanation:"1970年代臺灣出口貿易激增，舊有港口與陸運不堪負荷，推動十大建設（如公路、鐵路、港口）旨在消除交通運輸瓶頸。" },
    { id:"g21", difficulty:"medium", text:"澳洲東部有一座南北走向的大分水嶺，使得山脈東側迎風面降水豐沛，而山脈西側背風面則形成乾燥的草原與沙漠。請問造成東側迎風面降水豐富的主要風帶或氣流為何？", options:["盛行西風","東南信風","東北季風","極地東風"], answer:1, explanation:"澳洲大部分位於南半球副熱帶地區，東岸位於東南信風迎風面，信風帶來海洋水氣經大分水嶺抬升形成地形雨。" },
    { id:"g22", difficulty:"hard",   text:"「極地冰川融化導致地表對太陽輻射的反射率降低，進一步吸收更多熱量，加速冰川融化。」請問這種現象在系統地理學中屬於何種反饋機制？", options:["正反饋（Positive Feedback）","負反饋（Negative Feedback）","平衡狀態","零反饋"], answer:0, explanation:"正反饋機制指系統運作的結果會進一步強化或加速初始的變化過程（冰融→反射率降→吸熱多→加速冰融）。" },

    // ===== 模擬學測地理（下）閱讀題單選 Q26, Q28, Q30 =====
    { id:"g23", difficulty:"medium", text:"根據以下情境：沿海地區因長期過度抽取地下水，導致地層下陷與海水倒灌，部分農地演變為積水不退的濕地。請問長期抽用地下水主要引發了下列哪一項環境災害？", options:["石灰岩溶蝕","地層下陷與土壤鹽鹼化","火山噴發","冰河侵蝕"], answer:1, explanation:"沿海地區過度抽取地下水會導致孔隙水壓下降，引發地層下陷與海水倒灌（導致土壤鹽鹼化）。" },
    { id:"g24", difficulty:"medium", text:"根據以下情境：政府在地層下陷的沿海地區推動「漁電共生」，在廢棄養殖池上架設太陽能光電板。請問「漁電共生」主要試圖結合哪兩種產業模式？", options:["水產養殖業與再生能源（太陽能光電）","重工業製造與林業","商業性畜牧業與水力發電","高科技半導體與採礦業"], answer:0, explanation:"「漁電共生」指在水產養殖池上方架設太陽能光電板，結合綠能發電與養殖事業。" },
    { id:"g25", difficulty:"medium", text:"若要評估沿海地區設置太陽能光電板對周邊水鳥棲地與濕地生態的影響，環境評估人員最適合使用下列哪一種地理資訊技術進行長期地表覆蓋變化的監測？", options:["衛星遙測（Remote Sensing, RS）","GPS 全球定位系統","門牌地址定位","最短路徑導航分析"], answer:0, explanation:"衛星遙測（RS）具備大範圍、週期性拍攝的特點，最適合用來監測地表覆蓋（如光電板鋪設、水體面積變化）的長期變遷。" },
  ],

  civics: [
    { id:"cv1", difficulty:"easy", text:"依據中華民國憲法，行政院院長由誰任命？", options:["立法院","司法院","總統","監察院"], answer:2, explanation:"依中華民國憲法增修條文，行政院院長由總統任命，不需經立法院同意。" },
    { id:"cv2", difficulty:"easy", text:"台灣現行的選舉制度，投票年齡下限為？", options:["16歲","18歲","20歲","22歲"], answer:1, explanation:"2022年修憲後，公民投票年齡已降至18歲，2023年起全面適用18歲選舉權。" },
    { id:"cv3", difficulty:"medium", text:"依市場機制，當某商品需求增加而供給不變時，價格會如何變動？", options:["下降","不變","上升","先升後降"], answer:2, explanation:"需求增加，需求曲線右移，在供給不變的情況下，均衡價格會上升，均衡數量也增加。" },
    { id:"cv4", difficulty:"medium", text:"「法律之前，人人平等」體現了哪種法律原則？", options:["比例原則","信賴保護原則","平等原則","明確性原則"], answer:2, explanation:"平等原則：相同事物應給予相同對待，不同事物給予不同對待，禁止恣意差別對待。" },
    { id:"cv5", difficulty:"hard", text:"下列何者屬於「社會基本權」？", options:["言論自由","財產權","工作權","人身自由"], answer:2, explanation:"工作權屬於社會基本權（社會權），包含工作、生存、受教育等權利，需要國家積極作為來保障。" },

    // ===== 模擬學測公民（上）單選題 Q1–Q10 =====
    { id:"cv6",  difficulty:"easy",   text:"某國政府規定市民在公共場所聚集超過一定人數時必須事先申請許可，部分公民團體認為此規定過度限制了人民透過集會表達意見的權利。請問這主要涉及憲法所保障的哪一項基本權利？", options:["人身自由","言論自由","集會自由","結社自由"], answer:2, explanation:"人民在公共場所聚集表達意見屬於《憲法》第14條保障之「集會自由」。" },
    { id:"cv7",  difficulty:"medium", text:"關於未成年人或行為能力人的法律行為，下列敘述何者正確？", options:["無行為能力人所為的純獲法律上利益之行為無效","限制行為能力人未經法定代理人同意所購買的日常用品（如便當）無效","完全行為能力人得獨立做出具法律效力的契約行為","限制行為能力人未經允許所締結的房屋買賣契約一律無效"], answer:2, explanation:"完全行為能力人（如成年人）得獨立為一切法律行為。(A)純獲利益之行為對無行為能力人仍有效；(B)日常必需品無須代理人同意；(D)未經允許之契約為「效力未定」而非一律無效。" },
    { id:"cv8",  difficulty:"medium", text:"強調「法律為最高權威，政府權力必須受法律約束」的原則稱為？", options:["主權在民原則","法治主義（法治國原則）","分權制衡原則","多數決原則"], answer:1, explanation:"「法治主義」（法治國原則）強調法律具有最高權威，政府一切行政行為均須依法有據，且權力受法律限制。" },
    { id:"cv9",  difficulty:"easy",   text:"當市場上某種商品出現「供不應求」（短缺）的情況時，在自由市場機制運作下，該商品的市場價格通常會產生何種變化？", options:["價格下跌","價格上漲","價格維持不變","價格跌至零"], answer:1, explanation:"當市場出現短缺（需求量大於供給量）時，買方競爭會促使價格上漲，直到市場達到新平衡。" },
    { id:"cv10", difficulty:"medium", text:"我國憲法增修條文規定，立法院得對行政院院長提出何種議案，若獲得全體立法委員過半數贊成，行政院院長應辭職？", options:["彈劾案","罷免案","不信任案","覆議案"], answer:2, explanation:"根據我國憲法增修條文，立法院得對行政院院長提出「不信任案」（倒閣案）；若通過，行政院院長應辭職，並得呈請總統解散立法院。" },
    { id:"cv11", difficulty:"medium", text:"在刑法審判中，法官強調「非經合法審判，不得認定被告有罪」，且在判決確定前應推定被告無罪。請問這項法治原則稱為？", options:["罪刑法定原則","無罪推定原則","比例原則","誠實信用原則"], answer:1, explanation:"「無罪推定原則」指任何人在未經審判證明有罪確定前，均應推定其為無罪，為刑事訴訟保障人權的核心原則。" },
    { id:"cv12", difficulty:"medium", text:"政府針對香菸、含糖飲料課徵專用稅（如菸品健康福利捐）。從經濟學角度來看，政府此舉的主要目的為何？", options:["矯正該商品產生的負外部性（外部成本）","補貼生產者以增加供給","消除市場上的壟斷現象","提高消費者剩餘"], answer:0, explanation:"吸菸或過量攝取含糖飲料會增加社會整體醫療支出（負外部性/外部成本），政府對其課稅旨在提高消費成本，將外部成本內部化。" },
    { id:"cv13", difficulty:"medium", text:"當我國立法院通過之法律，被認為有牴觸憲法疑義時，應由哪一個機關進行憲法審查並做出判決？", options:["最高法院","最高行政法院","憲法法庭（司法院大法官）","監察院"], answer:2, explanation:"我國由司法院大法官組成「憲法法庭」，負責審理法律或法規是否違憲之案件。" },
    { id:"cv14", difficulty:"easy",   text:"一位礦工的子女透過教育與努力，成年後成為一名外科醫師。請問這種現象屬於哪一種社會流動？", options:["垂直流動（垂直向上流動）","水平流動","世代內流動","結構性流動"], answer:0, explanation:"子女的職業與社經地位高於父母，屬於跨世代的「垂直向上流動」。" },
    { id:"cv15", difficulty:"easy",   text:"我國《勞動基準法》規定勞工每日正常工作時間與加班上限，並規範雇主須支付加班費。請問此類法規的主要目的為何？", options:["維護契約自由原則","保護經濟弱勢的勞工，確保其基本勞動條件","鼓勵企業追求利潤最大化","促進資本自由流動"], answer:1, explanation:"《勞動基準法》為保護性勞動法規，旨在透過國家介入設定最低勞動條件，保障處於經濟弱勢的勞工。" },

    // ===== 模擬學測公民（下）單選題 Q16–Q22 =====
    { id:"cv16", difficulty:"medium", text:"某甲在網路上未經允許私自公開某乙的個人住址、電話與醫療病歷，導致某乙遭到網友騷擾，某乙決定向法院提告要求損害賠償。請問某甲行為主要侵犯了某乙的何種人格權？", options:["身體權","隱私權","肖像權","信用權"], answer:1, explanation:"未經同意公開他人個人資料（地址、電話、病歷）屬於侵害個人隱私權與個資法保障之權益。" },
    { id:"cv17", difficulty:"medium", text:"若選民認為選舉過程中選務機關辦理選舉違法，足以影響選舉結果，得向法院提起何種訴訟？", options:["選舉無效之訴","當選無效之訴","國家賠償之訴","行政處分撤銷之訴"], answer:0, explanation:"《公職人員選舉罷免法》規定，若選務機關辦理選舉違法足以影響結果，得提起「選舉無效之訴」；若係候選人有賄選等違法情事，則提起「當選無效之訴」。" },
    { id:"cv18", difficulty:"hard",   text:"甲國生產一單位小麥需要2小時、布料需要4小時；乙國生產小麥需要5小時、布料需要6小時。根據比較利益法則，甲國應專門生產哪種商品？", options:["小麥","布料","兩者皆專門生產","兩者皆不生產"], answer:0, explanation:"甲國生產小麥的機會成本（0.5單位布料）低於乙國（約0.83單位布料），甲國在小麥上具比較利益，應專門生產小麥。" },
    { id:"cv19", difficulty:"medium", text:"某國家因中央銀行大量印製鈔票，導致貨幣購買力急遽下降，物價持續飆漲，民眾需要背著一袋袋鈔票去買麵包。請問這種經濟現象稱為？", options:["通貨緊縮（Deflation）","惡性通貨膨脹（Hyperinflation）","滯脹（Stagflation）","邊際效益遞減"], answer:1, explanation:"政府過度發行貨幣導致物價極端暴漲、貨幣大幅貶值之現象稱為惡性通貨膨脹（Hyperinflation）。" },
    { id:"cv20", difficulty:"medium", text:"警察機關發紅線違規停車罰單時，未依法記載被處分人之姓名或違規事實，該行政處分可能因違反何種原則而無效或得撤銷？", options:["明確性原則","平等原則","信賴保護原則","比例原則"], answer:0, explanation:"「明確性原則」要求行政行為之內容、理由及法律依據必須明確，使人民得以預見與瞭解。" },
    { id:"cv21", difficulty:"medium", text:"各國為了吸引跨國企業投資，競相調降企業稅率或放寬勞動與環保標準，導致整體社會福利與環境品質向下沉淪。請問這種現象稱為？", options:["各國紛紛提高關稅以保護本土產業","底線競爭（Race to the bottom）","各國企業透過提升技術研發進行優質競爭","各國政府加強社會福利制度以照顧弱勢族群"], answer:1, explanation:"全球化下，各國競相削減企業稅或降低勞工與環境管制標準，導致整體社會福利與環境品質向下沉淪，稱為「底線競爭」。" },
    { id:"cv22", difficulty:"easy",   text:"我國《消費者保護法》規定，消費者透過通訊交易（如網路購物）購買商品，原則上享有幾天內的無條件解約退貨權（七天鑑賞期）？", options:["3天","5天","7天","30天"], answer:2, explanation:"《消費者保護法》第19條規定，通訊交易或訪問交易之消費者，得於收到商品後7日內無條件解約退貨。" },

    // ===== 模擬學測公民（下）閱讀題單選 Q26, Q28, Q30 =====
    { id:"cv23", difficulty:"medium", text:"某市政府未召開公聽會便宣布在偏遠鄉鎮設立大型廢棄物焚化與生質能發電廠，當地居民強烈反彈。請問居民對政府政策表達不滿，主要係因政府決策過程缺乏下列哪一種現代民主政治的核心價值？", options:["審議民主與公民參與","絕對多數決原則","自由放任主義","階級對立"], answer:0, explanation:"市府未經公開溝通與聽證即拍板決策，缺乏「公民參與」與「審議民主」的精神。" },
    { id:"cv24", difficulty:"medium", text:"若居民認為市府設置發電廠的行政處分違法且損害其權益，在提起「行政訴訟」之前，原則上應先進行何種行政救濟程序？", options:["民事訴訟","訴願","請願","刑事告發"], answer:1, explanation:"依據我國《行政訴訟法》，對不服行政機關之行政處分，原則上須先經過「訴願」程序（訴願前置主義），若不服訴願決定始得提起行政訴訟。" },
    { id:"cv25", difficulty:"easy",   text:"居民若透過集結抗議、遞交陳情書等方式表達訴求，這是屬於憲法保障的何種公民參政或基本權利之展現？", options:["人身自由與居住遷徙自由","請願權與集會自由","服公職權與創制複決權","受教育權與工作權"], answer:1, explanation:"居民向政府遞交陳情書屬於《憲法》保障之「請願權」，號召集結抗議則屬於「集會自由」。" },
  ],

  exam_gaokao: [
    // ===== 國文 =====
    { id:"ex_c1", year:2023, subject:"國文", difficulty:"medium", text:"「天下皆知美之為美，斯惡已；皆知善之為善，斯不善已。」此段出自？", options:["《論語》","《孟子》","《道德經》","《莊子》"], answer:2, explanation:"此段出自老子《道德經》第二章，說明美醜、善惡是相對的概念。" },
    { id:"ex_c2", year:2021, subject:"國文", difficulty:"hard", text:"「吾十有五而志於學，三十而立，四十而不惑，五十而知天命，六十而耳順，七十而從心所欲，不踰矩。」此段出自？", options:["《孟子》","《論語》","《中庸》","《大學》"], answer:1, explanation:"此段出自《論語·為政篇》，是孔子自述一生學習修養的歷程。" },
    { id:"ex_c3", year:2022, subject:"國文", difficulty:"medium", text:"「先天下之憂而憂，後天下之樂而樂」出自哪篇文章？", options:["《師說》","《出師表》","《岳陽樓記》","《赤壁賦》"], answer:2, explanation:"此句出自北宋范仲淹的《岳陽樓記》，表達了憂國憂民、以天下為己任的高尚情操。" },
    { id:"ex_c4", year:2020, subject:"國文", difficulty:"easy", text:"「床前明月光，疑是地上霜」的作者是？", options:["杜甫","王維","李白","孟浩然"], answer:2, explanation:"此句出自唐代詩人李白的《靜夜思》，描寫遊子思鄉之情。" },
    { id:"ex_c5", year:2023, subject:"國文", difficulty:"hard", text:"下列哪個文言虛詞「而」是表示「轉折」的用法？", options:["學而時習之","任重而道遠","人不知而不慍","吾日三省吾身"], answer:2, explanation:"「人不知而不慍」中的「而」表示轉折（但是、卻），意為「別人不了解我，我卻不生氣」。" },
    { id:"ex_c6", year:2022, subject:"國文", difficulty:"medium", text:"《桃花源記》的作者是哪個朝代的人？", options:["唐代","宋代","東晉","明代"], answer:2, explanation:"《桃花源記》作者陶淵明（陶潛）是東晉時代的著名詩人，以田園詩著稱。" },
    { id:"ex_c7", year:2021, subject:"國文", difficulty:"easy", text:"「山重水複疑無路，柳暗花明又一村」出自哪位詩人？", options:["陸游","蘇軾","辛棄疾","杜甫"], answer:0, explanation:"此句出自南宋陸游的《遊山西村》，比喻在困境中出現轉機。" },
    { id:"ex_c8", year:2020, subject:"國文", difficulty:"hard", text:"下列哪一項不是「論語」的體裁特徵？", options:["語錄體","記載孔子及弟子言行","四書之一","敘事完整的長篇散文"], answer:3, explanation:"《論語》是語錄體散文，記載孔子及弟子言行，篇幅短小，不是敘事完整的長篇散文。" },
    { id:"ex_c9",  year:2022, subject:"國文", difficulty:"medium", text:"下列「」內的字，讀音前後相同的是？", options:["既瘖且「痺」／彈箏搏「髀」","不「忮」不求／「庋」藏字畫","「攢」蹙累積／踰牆「鑽」穴","「剜」肉補瘡／壯士斷「腕」"], answer:0, explanation:"(A)兩者皆讀「ㄅㄧˋ」；(B)ㄓˋ／ㄍㄨㄟˇ，讀音不同；(C)ㄘㄨㄢˊ／ㄗㄨㄢ，讀音不同；(D)ㄨㄢ／ㄨㄢˋ，讀音不同。大考極愛考核心古文與日常罕見詞彙的語音對比。" },
    { id:"ex_c10", year:2023, subject:"國文", difficulty:"medium", text:"下列文句，完全沒有錯別字的是？", options:["他的魔術表演精彩絕倫，台下觀眾看得目不暇給","這位演員將劇中反派角色演得入木三分、維妙維肖","面對經濟危機，政府必須當機立斷，否則將病入膏盲","他平日行事向來劍及履及，從不拖泥帶水"], answer:3, explanation:"(A)「目不暇給」正確，此句無誤，但（D）全無錯字。(B)應作「惟妙惟肖」；(C)應作「病入膏肓」；(D)「劍及履及」正確，全句無錯別字。" },
    { id:"ex_c11", year:2024, subject:"國文", difficulty:"medium", text:"下列「」中的字，前後意義相同的是？", options:["臣以神遇而不以目「視」／下「視」其轍，登軾而望之","顧玩「大」足，即其廬之","乃「使」人修復建康，以待天子之至／向使三國各愛其地","「微」夫人之力不及此／微斯人，吾誰與歸"], answer:3, explanation:"(D)兩者皆為「（如果）沒有」之意：「微夫人之力不及此」出自〈燭之武退秦師〉，「微斯人，吾誰與歸」出自〈岳陽樓記〉，古今詞義相同。" },
    { id:"ex_c12", year:2025, subject:"國文", difficulty:"medium", text:"依據〈勸學〉與儒家思想，下列關於「學」的敘述何者正確？", options:["荀子認為人必須透過學習改變惡性，與孟子強調發揚善端不同","兩者都認為只要不學習，人性就會徹底淪喪","荀子與孟子在人性論上觀點相同，都主張後天學習的重要性","孟子認為學習無法改變天生善性，因此不強調後天修養"], answer:0, explanation:"荀子主「性惡」，強調後天「偽」（人為改造）透過學習化性起偽；孟子主「性善」，強調透過學習擴充、發揚四端善端。兩者學習觀的出發點不同。" },
    { id:"ex_c13", year:2022, subject:"國文", difficulty:"medium", text:"韓愈〈師說〉中「巫醫樂師百工之人，不恥相師」的用意在於？", options:["讚美底層階級的謙虛好學","諷刺當時士大夫階層「恥學於師」的怪現象","說明醫師與樂師職業地位的平等","強調各行各業都應互相學習以求進步"], answer:1, explanation:"韓愈運用「對比法」，以百工之人的「不恥相師」反襯士大夫「恥學於師」的怪現象，諷刺其愚昧自大。" },
    { id:"ex_c14", year:2023, subject:"國文", difficulty:"medium", text:"洪繻在〈鹿港乘桴記〉中所展現的核心情感為何？", options:["讚嘆商業繁榮與都市現代化","感傷家國變遷與鹿港的滄海桑田","對日治新政府的肯定與期待","記錄乘船旅途中的所見所聞"], answer:1, explanation:"〈鹿港乘桴記〉是108課綱新增的臺灣核心古文，作者洪繻（洪棄生）藉由描寫日治初期鹿港的沒落景象，表達對家國變遷的悲涼與滄海桑田之感慨。" },
    { id:"ex_c15", year:2024, subject:"國文", difficulty:"medium", text:"歸有光在〈項脊軒志〉中透過「多得情景」的空間描寫，主要是為了表達？", options:["家族人情物事變遷的悲喜交集","考取功名的遠大志向","對項脊軒建築本身的喜愛","以景喻情，諷刺社會現實"], answer:0, explanation:"〈項脊軒志〉借「項脊軒」的修復、破敗與周遭親人的回憶交織，展現「借物抒情」的手法，傳達對家族變遷與親人離去的悲喜交集。" },
    { id:"ex_c16", year:2026, subject:"國文", difficulty:"hard", text:"柳宗元寫西山「特立拔萃，不與培塿為類」，此句暗喻作者何種心境？", options:["隨遇而安，與世無爭","堅持高潔人格，不與流俗同流合污","羨慕西山的雄偉景致，嚮往歸隱山林","感嘆自身才能無法得到施展"], answer:1, explanation:"柳宗元以「移情入景」手法，將西山的獨特景致（特立拔萃，不與培塿為類）轉化為自身傲骨與不妥協的政治態度，暗喻其堅持高潔人格、不隨波逐流的精神。" },
    { id:"ex_c17", year:2025, subject:"國文", difficulty:"medium", text:"李斯在〈諫逐客書〉中，大量列舉秦王喜愛異國音樂、美女、珠玉的目的是？", options:["批評秦王奢靡無度","採「以物擬人」手法，駁斥「跨海內制諸侯」不應排斥外來人才","讚美秦國文化的包容性","說明秦國國力強盛，不需仰賴外來人才"], answer:1, explanation:"李斯運用「類比論證」，以秦王廣納異國珠玉、音樂、美女為例，反問秦王為何獨對人才要採取逐客令，強調「重物輕人、因噎廢食」的矛盾。" },
    { id:"ex_c18", year:2022, subject:"國文", difficulty:"medium", text:"張李德和在〈畫菊自序〉中提到「兼慕管夫人之墨竹」，主要傳達其何種自我期許？", options:["期待能相夫教子，成為模範家庭主婦","展現女性在詩文書畫上的自主意識與才華追求","表達對中國傳統水墨畫技法的景仰","強調繪畫創作需遵循古人典範"], answer:1, explanation:"〈畫菊自序〉是108課綱新增的臺灣選文，作者張李德和藉此表達女性在詩文書畫藝術上的自主意識，重塑女性的文化主體性與才華追求。" },
    { id:"ex_c19", year:2023, subject:"國文", difficulty:"medium", text:"下列各句「」內的成語，運用最適當的是？", options:["他的演講觀點新穎，「陳言務去」，深獲好評","警方這次行動落空，讓主嫌「壽終正寢」","他做事總是「好整以暇」，讓同事十分焦急","這件事「無足輕重」，我們應該全力以赴"], answer:0, explanation:"「陳言務去」指陳舊的言詞務必刪去，適合形容演講或寫作觀點新穎；(B)「壽終正寢」指老死在家中，不可用於罪犯逃脫；(C)「好整以暇」指從容不迫，但語境暗示需要緊張；(D)「無足輕重」與「全力以赴」矛盾。" },
    { id:"ex_c20", year:2024, subject:"國文", difficulty:"easy", text:"小明寫信給老師，下列書信用語何者完全正確？", options:["欣逢「令尊」大壽，特此祝賀","明日我將親自到「貴府」拜訪","敬請「惠存」此函，以備日後查驗","謹呈「犬子」一事，敬請裁奪"], answer:0, explanation:"「令尊」是敬稱對方父親的用語，用於祝賀老師父親大壽正確；(B)「貴府」是稱對方家，而稱自己家應用「寒舍」；(C)「惠存」指請對方保存，用法可接受但(A)更具針對性；(D)「犬子」是謙稱自己兒子，不可用於向老師陳述事情。" },
    { id:"ex_c21", year:2022, subject:"國文", difficulty:"medium", text:"下列詩句，何者運用了「互文」的修辭手法？", options:["主人下馬客在船，舉酒欲飲無管弦","潯陽江頭夜送客，楓葉荻花秋瑟瑟","千里鶯啼綠映紅，水村山郭酒旗風","烽火連三月，家書抵萬金"], answer:0, explanation:"〈琵琶行〉「主人下馬客在船」應理解為「主人和客人一同下馬、一同上船」，兩者互文，此為典型的互文見義結構。" },
    { id:"ex_c22", year:2026, subject:"國文", difficulty:"medium", text:"關於一首標準的七言律詩，下列敘述何者錯誤？", options:["第三、四句（頷聯）與第五、六句（頸聯）必須對仗","全詩只能在雙數句押韻，第一句絕對不能押韻","全詩共八句，分為首聯、頷聯、頸聯、尾聯","律詩押平聲韻，且一韻到底不可換韻"], answer:1, explanation:"七言律詩第一句可押可不押（若押韻則押平聲韻），並非絕對不能押韻；雙數句（二、四、六、八句）則必須押韻。其餘選項均正確。" },
    { id:"ex_c23", year:2025, subject:"國文", difficulty:"medium", text:"關於「詞」與「散曲」的比較，下列何者正確？", options:["詞與曲皆有詞牌、曲牌，且皆可自由加入「襯字」","詞不可加襯字，散曲則可自由加襯字，風格較為俚俗","詞與散曲同樣以格律嚴整著稱，皆不可隨意增減字數","散曲興起於唐代，詞則是宋代才逐漸發展成熟"], answer:1, explanation:"散曲最大的特色就是可加「襯字」，展現庶民化與活潑的語言風格；詞則有嚴格的字數與平仄格律限制，不可加襯字。" },
    { id:"ex_c24", year:2023, subject:"國文", difficulty:"easy", text:"下列關於中國古典小說的敘述，何者正確？", options:["《世說新語》是著名的神怪小說","《聊齋誌異》是清代著名的文言短篇志怪小說","《水滸傳》是中國最早的章回小說","《儒林外史》以描寫俠義精神為主題"], answer:1, explanation:"《聊齋誌異》為清代蒲松齡所著，是文言短篇小說的巔峰之作，以志怪為主；(A)《世說新語》是筆記小說（記言記行），非神怪小說；(C)最早章回小說一般公認為《三國演義》；(D)《儒林外史》以諷刺科舉制度為主題。" },
    { id:"ex_c25", year:2024, subject:"國文", difficulty:"easy", text:"蘇軾〈赤壁賦〉中「月出於東山之上，徘徊於斗牛之間」，其中的「斗牛」是指？", options:["兩種動物的爭鬥","二十八星宿中的斗宿與牛宿","指月亮的運行軌跡","形容月光如牛角般彎曲"], answer:1, explanation:"「斗牛」指二十八星宿中的斗宿與牛宿，體現文學作品中的天文常識，也反映新課綱跨學科素養的命題趨勢。" },
    { id:"ex_c26", year:2025, subject:"國文", difficulty:"hard", text:"閱讀文本甲（文言文：戰國策）與文本乙（現代賽局理論），兩文共同說明的核心觀念是？", options:["如何在資訊不對稱下做出最有利的決策","古代戰爭與現代經濟學的全然矛盾","古人重情義，今人重利益","文言文與白話文的語法結構差異"], answer:0, explanation:"混合題大宗考題，要求考生將古人的政治智慧（戰國策中的謀略）與現代科學理論（賽局理論）進行跨時空對話與歸納，共同主題為資訊不對稱下的最優決策。" },
    { id:"ex_c27", year:2026, subject:"國文", difficulty:"hard", text:"混合題型：給予「近年臺灣獨立書店數量消長圖」及一段白話文本，請問書店轉型的關鍵為何？（依據非連續性文本綜合判讀）", options:["持續降低書籍售價以吸引消費者","轉型為複合式文化空間，結合咖啡、展覽、講座等多元體驗","仰賴政府補貼以維持營運","擴大網路書店銷售規模以取代實體書店"], answer:1, explanation:"此題考察「非連續性文本」的閱讀能力。從圖表的數量消長趨勢與文本分析，書店轉型關鍵在於跳脫純售書模式，轉型為提供多元文化體驗的複合式空間，以創造獨特的實體消費價值。" },
    { id:"ex_c28", year:2022, subject:"國文", difficulty:"hard", text:"評析《禮記》〈大同與小康〉中「城郭溝池以為固，禮義以為紀」在小康社會的功能，下列何者最符合文意？", options:["城郭溝池象徵大同社會的和諧，禮義則是維繫公共信任的基礎","小康社會因私有制興起，需藉由城牆、禮法等制度維繫社會秩序與穩定","城郭的建立旨在促進商業貿易，禮義則是為了選賢與能","大同社會的「選賢與能、講信修睦」精神延伸至小康社會的城牆建設"], answer:1, explanation:"〈大同與小康〉中，大同社會「天下為公」，無需城郭禮法；小康社會「大道既隱，天下為家」，私有制興起後，必須藉由「城郭溝池以為固、禮義以為紀」等外在制度與法律來維繫社會的穩定秩序。" },

    // ===== 英文 =====
    { id:"ex_e1", year:2023, subject:"英文", difficulty:"medium", text:"Choose the best answer: The scientist's experiment was ___; it produced results that no one had expected.", options:["conventional","groundbreaking","redundant","trivial"], answer:1, explanation:"\"groundbreaking\" means innovative and pioneering, which fits the context of unexpected results." },
    { id:"ex_e2", year:2020, subject:"英文", difficulty:"hard", text:"The phrase \"turn over a new leaf\" means:", options:["to change one's behavior for the better","to literally turn a page","to start a new book","to ignore past mistakes"], answer:0, explanation:"\"Turn over a new leaf\" is an idiom meaning to start behaving in a better or more responsible way." },
    { id:"ex_e3", year:2022, subject:"英文", difficulty:"medium", text:"Choose the correct form: She ___ to the gym every day before she got injured.", options:["goes","went","has gone","will go"], answer:1, explanation:"過去習慣用過去式 \"went\"，表示過去規律性的動作（在受傷之前）。" },
    { id:"ex_e4", year:2021, subject:"英文", difficulty:"easy", text:"Which word means the opposite of \"ancient\"?", options:["old","historic","modern","traditional"], answer:2, explanation:"\"modern\" means contemporary or new, which is the opposite of \"ancient\" (very old)." },
    { id:"ex_e5", year:2023, subject:"英文", difficulty:"hard", text:"___ he studied hard, he failed the exam.", options:["Because","Although","Since","Unless"], answer:1, explanation:"\"Although\" introduces a contrast/concession clause, meaning 'despite the fact that he studied hard, he still failed'." },
    { id:"ex_e6", year:2022, subject:"英文", difficulty:"medium", text:"The word \"meticulous\" most closely means:", options:["careless","showing great attention to detail","very fast","generous"], answer:1, explanation:"\"Meticulous\" means showing great attention to detail, being very careful and precise." },
    { id:"ex_e7", year:2021, subject:"英文", difficulty:"easy", text:"Choose the correct preposition: She is very good ___ playing the piano.", options:["in","on","at","for"], answer:2, explanation:"\"good at\" is the correct collocation when describing someone's skill or ability in an activity." },
    { id:"ex_e8", year:2020, subject:"英文", difficulty:"hard", text:"The passive voice of \"The teacher will explain the rules\" is:", options:["The rules will be explained by the teacher","The rules are explained by the teacher","The teacher is explaining the rules","The rules were explained by the teacher"], answer:0, explanation:"未來式主動 → 未來式被動：will + be + past participle。\"The rules will be explained by the teacher.\"" },
    { id:"ex_e9",  year:2023, subject:"英文", difficulty:"medium", text:"The company had to ______ its marketing strategy to appeal to younger customers.", options:["adopt","adapt","adept","addict"], answer:1, explanation:"辨析形近字：adapt (v.) 適應、改編策略；adopt (v.) 採用、收養；adept (adj.) 熟練的（形容詞，不可填入動詞位置）；addict (v.) 使上癮。此句需要「調整、改編」之意，選 adapt。" },
    { id:"ex_e10", year:2024, subject:"英文", difficulty:"medium", text:"Mary felt ______ about which university to choose, as both options seemed equally attractive.", options:["ambivalent","ambiguous","ambitious","artificial"], answer:0, explanation:"ambivalent（矛盾的、有矛盾情感的）：指內心同時存在兩種相反情感；ambiguous（模稜兩可的）：指言語或意思含糊不清。本句主詞 Mary 對選校感到兩難，心情矛盾，故選 ambivalent。" },
    { id:"ex_e11", year:2025, subject:"英文", difficulty:"medium", text:"The internet has advanced to the point where the ______ between the virtual and real worlds is blurring.", options:["separation","isolation","boundary","horizon"], answer:2, explanation:"boundary (n.) 邊界、界線，為最符合「虛擬與現實世界之間界線模糊」的用詞。separation 指分離；isolation 指孤立；horizon 指水平線或視野，均不如 boundary 貼切。" },
    { id:"ex_e12", year:2022, subject:"英文", difficulty:"medium", text:"Medical experts are working hard to ______ the virus before it spreads further.", options:["contaminate","contain","preserve","sustain"], answer:1, explanation:"contain 除了「包含」，在公衛語境中常考「控制、遏制（疾病或火勢）」的意思，為大考高頻用法。contaminate 指污染；preserve 指保存；sustain 指維持，均不符合「阻止病毒擴散」的語意。" },
    { id:"ex_e13", year:2023, subject:"英文", difficulty:"medium", text:"Rome is a historic city, ______ many ancient monuments can be found.", options:["which","where","that","what"], answer:1, explanation:"空格後方為完整子句（many ancient monuments can be found），且先行詞 Rome 為地點，故用關係副詞 where（等同於 in which）。若選 which 則後方須接不完整子句（缺主詞或受詞）。" },
    { id:"ex_e14", year:2022, subject:"英文", difficulty:"medium", text:"______ by the beautiful scenery, the tourists took hundreds of photos.", options:["Fascinated","Fascinating","Fascinate","To fascinate"], answer:0, explanation:"分詞構句：主詞 the tourists 對 fascinate（使著迷）的關係為「被動（感到著迷）」，省略主詞後動詞轉為過去分詞（V-ed）。若主詞主動引起迷人感，才用 Fascinating（V-ing）。" },
    { id:"ex_e15", year:2024, subject:"英文", difficulty:"hard", text:"______ hard he tried, he could not solve the complex math problem.", options:["Although","Despite","However","Whatever"], answer:2, explanation:"However + adj./adv. + 主詞 + 動詞，表示「無論多麼…」，此句為 However hard he tried（無論他多努力）。選 Although 後方應接正常主詞動詞語序（Although he tried hard）；Despite 後接名詞片語，不接子句。" },
    { id:"ex_e16", year:2026, subject:"英文", difficulty:"hard", text:"At the top of the mountain ______ a small, peaceful temple.", options:["stands","standing","does it stand","is stood"], answer:0, explanation:"地方副詞（介系詞片語 At the top of the mountain）放句首時，句子全倒裝：地方副詞 + 動詞 + 主詞。主詞 a temple 為單數，故選第三人稱單數 stands。stands 為不及物動詞，無被動語態。" },
    { id:"ex_e17", year:2025, subject:"英文", difficulty:"hard", text:"If the driver ______ more careful, the accident would not have happened last night.", options:["was","had been","would be","were"], answer:1, explanation:"後半句 would not have happened 為過去完成式，表示與「過去事實相反」的假設語氣（第三條件句）。If 子句須使用過去完成式（had + V-pp），故選 had been。were 用於與現在事實相反的假設語氣。" },
    { id:"ex_e18", year:2023, subject:"英文", difficulty:"medium", text:"Some people prefer online shopping. ______, others still enjoy visiting physical stores.", options:["In short","By contrast","Consequently","Furthermore"], answer:1, explanation:"By contrast（相反地、相比之下）用來對比兩種不同現象，最符合前後句語意對立（網購 vs 實體店）。In short（總而言之）為結論；Consequently（因此）為因果；Furthermore（此外）為補充。" },
    { id:"ex_e19", year:2024, subject:"英文", difficulty:"medium", text:"The flight was canceled ______ the heavy snowstorm.", options:["on account of","with a view to","in terms of","in spite of"], answer:0, explanation:"on account of 等同於 because of（因為），表示原因。with a view to（為了）；in terms of（就…而言）；in spite of（儘管），均不符合「因暴風雪而取消」的因果語意。" },
    { id:"ex_e20", year:2022, subject:"英文", difficulty:"medium", text:"______ English, Jeremy can also speak fluent Japanese and French.", options:["Except for","In addition to","Rather than","Instead of"], answer:1, explanation:"In addition to（除了…之外還有，包含後者）：Jeremy 除了英文之外，還會說日文和法文，兩者都包含。Except for（除了…之外，排除後者）；Rather than（而非）；Instead of（代替），均不符合語意。" },

    // ===== 數學 =====
    { id:"ex_m1", year:2022, subject:"數學", difficulty:"hard", text:"設 a, b 為正整數，且 a + b = 10，則 ab 的最大值為？", options:["21","24","25","30"], answer:2, explanation:"由 AM-GM 不等式，當 a = b = 5 時，ab 有最大值 5×5 = 25。" },
    { id:"ex_m2", year:2020, subject:"數學", difficulty:"hard", text:"若 log₂8 = x，則 x = ？", options:["2","3","4","8"], answer:1, explanation:"log₂8 = log₂(2³) = 3，因為 2³ = 8。" },
    { id:"ex_m3", year:2023, subject:"數學", difficulty:"medium", text:"等差數列首項為 2，公差為 3，則第 10 項為？", options:["27","29","32","30"], answer:1, explanation:"等差數列第 n 項 = a₁ + (n-1)d = 2 + (10-1)×3 = 2 + 27 = 29。" },
    { id:"ex_m4", year:2021, subject:"數學", difficulty:"easy", text:"一個正六邊形的內角和為？", options:["540°","600°","720°","900°"], answer:2, explanation:"多邊形內角和 = (n-2)×180°，六邊形 = (6-2)×180° = 720°。" },
    { id:"ex_m5", year:2022, subject:"數學", difficulty:"medium", text:"若 f(x) = x² - 2x + 1，則 f(3) = ？", options:["2","4","6","8"], answer:1, explanation:"f(3) = 3² - 2×3 + 1 = 9 - 6 + 1 = 4。" },
    { id:"ex_m6", year:2020, subject:"數學", difficulty:"hard", text:"從 5 個不同顏色的球中取 3 個，有幾種取法？", options:["10","15","20","60"], answer:0, explanation:"組合 C(5,3) = 5!/(3!×2!) = (5×4)/(2×1) = 10 種。" },
    { id:"ex_m7", year:2023, subject:"數學", difficulty:"medium", text:"圓方程式 x² + y² = 25 的半徑為？", options:["5","10","25","√5"], answer:0, explanation:"標準圓方程式 x² + y² = r²，對照得 r² = 25，故 r = 5。" },
    { id:"ex_m8", year:2021, subject:"數學", difficulty:"hard", text:"sin30° × cos60° + cos30° × sin60° = ？", options:["0","1/2","√3/2","1"], answer:3, explanation:"此為 sin(30°+60°) = sin90° = 1，應用和角公式 sin(A+B) = sinAcosB + cosAsinB。" },

    // ===== 自然（物理＋化學＋生物）=====
    { id:"ex_n1", year:2022, subject:"自然", difficulty:"medium", text:"下列哪個物理量的單位是「帕斯卡（Pa）」？", options:["能量","壓力","力","速度"], answer:1, explanation:"帕斯卡（Pascal, Pa）是壓力的SI單位，等於每平方公尺施加1牛頓的力（N/m²）。" },
    { id:"ex_n2", year:2023, subject:"自然", difficulty:"easy", text:"光合作用的主要場所是細胞中的？", options:["粒線體","核糖體","葉綠體","細胞核"], answer:2, explanation:"葉綠體是植物進行光合作用的場所，含有葉綠素，可吸收光能。" },
    { id:"ex_n3", year:2021, subject:"自然", difficulty:"medium", text:"下列何者為酸性物質？", options:["氫氧化鈉（NaOH）","碳酸氫鈉（NaHCO₃）","鹽酸（HCl）","氨水（NH₃）"], answer:2, explanation:"鹽酸（HCl）是強酸，溶於水會完全解離出氫離子（H⁺），pH < 7。" },
    { id:"ex_n4", year:2020, subject:"自然", difficulty:"hard", text:"在密閉容器中，一定質量的理想氣體，溫度不變而體積縮小一半，壓力變為原來的？", options:["1/2倍","2倍","4倍","不變"], answer:1, explanation:"由波以耳定律（Boyle's Law）PV = 常數（溫度固定），體積縮半則壓力加倍。" },
    { id:"ex_n5", year:2023, subject:"自然", difficulty:"medium", text:"DNA 複製遵循的原則是？", options:["全保留複製","半保留複製","分散複製","隨機複製"], answer:1, explanation:"DNA 採半保留複製（Semiconservative Replication），複製後每條新 DNA 含有一條原有鏈和一條新合成鏈。" },
    { id:"ex_n6", year:2022, subject:"自然", difficulty:"hard", text:"電流通過導體時，其電阻與下列哪項因素無關？", options:["導體的材質","導體的長度","導體的截面積","通過的電流大小"], answer:3, explanation:"電阻 R = ρL/A，由材質（電阻率ρ）、長度（L）、截面積（A）決定，與通過的電流大小無關。" },
    { id:"ex_n7", year:2021, subject:"自然", difficulty:"easy", text:"下列哪個是化學變化？", options:["冰融化成水","鹽溶於水","鐵生鏽","玻璃破碎"], answer:2, explanation:"鐵生鏽（氧化反應）是化學變化，生成了新物質（氧化鐵）；其他三者為物理變化。" },
    { id:"ex_n8", year:2020, subject:"自然", difficulty:"medium", text:"人體消化澱粉的酵素是？", options:["蛋白酶","脂肪酶","澱粉酶","纖維素酶"], answer:2, explanation:"澱粉酶（Amylase）由唾液腺和胰腺分泌，負責將澱粉分解為麥芽糖和葡萄糖。" },

    // ===== 社會（歷史＋地理＋公民）=====
    { id:"ex_s1", year:2021, subject:"社會", difficulty:"medium", text:"聯合國《世界人權宣言》於哪一年通過？", options:["1945年","1946年","1948年","1950年"], answer:2, explanation:"聯合國《世界人權宣言》於1948年12月10日通過，確立了基本人權的普世標準。" },
    { id:"ex_s2", year:2023, subject:"社會", difficulty:"easy", text:"台灣的北回歸線橫貫哪個縣市附近？", options:["台中","嘉義","台南","彰化"], answer:1, explanation:"北回歸線（北緯23.5°）通過嘉義縣及花蓮縣，嘉義市設有北回歸線標誌。" },
    { id:"ex_s3", year:2022, subject:"社會", difficulty:"medium", text:"下列哪個事件標誌著冷戰的結束？", options:["韓戰結束","越戰結束","蘇聯解體","柏林圍牆建立"], answer:2, explanation:"1991年蘇聯解體，標誌著冷戰（Cold War）正式結束，美蘇兩極對立的格局消失。" },
    { id:"ex_s4", year:2020, subject:"社會", difficulty:"hard", text:"中華民國憲法規定，立法委員任期為幾年？", options:["3年","4年","5年","6年"], answer:1, explanation:"依中華民國憲法增修條文，立法委員任期為4年，得連選連任。" },
    { id:"ex_s5", year:2023, subject:"社會", difficulty:"medium", text:"「絲路」連接了古代中國與哪個地區的貿易往來？", options:["非洲","中亞與歐洲","東南亞","南美洲"], answer:1, explanation:"古代絲路（Silk Road）連接中國與中亞、西亞乃至歐洲，是重要的貿易與文化交流通道。" },
    { id:"ex_s6", year:2022, subject:"社會", difficulty:"easy", text:"台灣地形以哪種地形為主？", options:["平原","高原","山地與丘陵","盆地"], answer:2, explanation:"台灣地形約2/3為山地與丘陵，以中央山脈為脊樑，平原主要分布於西部沿岸。" },
    { id:"ex_s7", year:2021, subject:"社會", difficulty:"hard", text:"下列哪項是「外部性（Externality）」的例子？", options:["工廠生產商品獲利","消費者購買商品","工廠排放廢水污染河川","政府課徵所得稅"], answer:2, explanation:"外部性指經濟活動對第三方造成未計入市場價格的影響。工廠排放廢水污染河川是「負外部性」的典型例子。" },
    { id:"ex_s8", year:2020, subject:"社會", difficulty:"medium", text:"鄭成功驅逐荷蘭人、收復台灣是在哪一年？", options:["1624年","1661年","1683年","1895年"], answer:1, explanation:"1661年鄭成功率軍登陸台灣，1662年迫使荷蘭東印度公司投降，結束荷蘭在台38年的統治。" },

    // ===== 地理 =====
    { id:"ex_s9",  year:2023, subject:"地理", difficulty:"medium", text:"某市要評估「土石流高風險淹沒區」，並計算受災的人口總數。請問應使用 GIS 的哪一種分析功能？", options:["地形剖面分析","疊圖分析（Overlay）","最佳路徑分析","視域分析"], answer:1, explanation:"GIS 疊圖分析將多個圖層（坡度、土石流潛勢區、人口分布）進行交集/聯集運算，以找出同時符合多種空間條件的區域，是此情境的最適解。" },
    { id:"ex_s10", year:2024, subject:"地理", difficulty:"medium", text:"當一張地圖的網格解析度從 10 公尺改為 5 公尺時，原先 100 平方公尺的土地，在電腦中會從 1 個網格變成幾個網格？", options:["2 個","4 個","8 個","16 個"], answer:1, explanation:"解析度縮小一半（10m→5m），長與寬的格數各自加倍（2×2=4）。解析度愈小代表地圖愈精細，儲存數據量也變為 4 倍。" },
    { id:"ex_s11", year:2022, subject:"地理", difficulty:"medium", text:"觀看一張等高線地形圖，若等高線呈現「V 字型向低處凸出」，代表該處是何種地形？", options:["山脊（稜線）","山谷（集水區）","鞍部","窪地"], answer:0, explanation:"「等高線向低處凸出為脊，向高處凸出為谷」。山脊（稜線）的等高線向低處（數值小的方向）凸出，山谷則向高處（數值大的方向）凸出。" },
    { id:"ex_s12", year:2025, subject:"地理", difficulty:"medium", text:"某地區在北半球，夏季時受副熱帶高壓籠罩而炎熱乾燥，冬季時迎副極地低壓帶（西風帶）而溫和多雨。請問該地屬於何種氣候類型？", options:["熱帶莽原氣候","溫帶大陸性氣候","地中海型氣候","溫帶海洋性氣候"], answer:2, explanation:"地中海型氣候的成因為「風帶季移」：夏季受副熱帶高壓下沉氣流控制→乾熱；冬季西風帶北移帶來海洋水氣→溫濕。分布於南北緯30~40度大陸西岸。" },
    { id:"ex_s13", year:2024, subject:"地理", difficulty:"medium", text:"臺灣島受到板塊擠壓持續抬升，若在某海岸看到多層的「海蝕平臺」與「海階」地形，主要代表該地經歷了什麼地質過程？", options:["地殼局部下沉","陸地相對抬升","河流向源侵蝕","嚴重的沙洲淤積"], answer:1, explanation:"海階（離水海岸）是陸地相對於海平面快速抬升的證據。臺灣東部板塊隱沒帶使陸地持續上升，海蝕平臺被抬離海面後形成多層海階地形。" },
    { id:"ex_s14", year:2023, subject:"地理", difficulty:"medium", text:"秘魯沿岸之所以能成為全球著名的湧升流漁場，主要是受到哪一個風帶吹拂表層海水離岸所致？", options:["東南信風","東北信風","盛行西風","赤道無風帶"], answer:0, explanation:"南半球低緯的東南信風將表層海水向西北吹離岸邊，底層富含營養鹽的冷海水上湧，形成漁業資源豐富的湧升流漁場。這也是聖嬰現象（東南信風減弱）破壞漁場的關鍵背景。" },
    { id:"ex_s15", year:2026, subject:"地理", difficulty:"hard", text:"便利商店、大型好市多（Costco）賣場、以及醫學中心。這三者在都市空間中的「商閾（Threshold）」與「商品圈（Range）」大小關係為何？", options:["便利商店 > 好市多 > 醫學中心","醫學中心 > 好市多 > 便利商店","三者商品圈相同，僅服務品質有差異","好市多 > 醫學中心 > 便利商店"], answer:1, explanation:"依克里斯泰勒中地理論，高級中地（醫學中心）商閾與商品圈最大、數量最少、間距最遠；低級中地（便利商店）商品圈小、數量最多、間距最近。" },
    { id:"ex_s16", year:2022, subject:"地理", difficulty:"medium", text:"臺灣中南部部分稻作區近年轉作為「溫室精緻花卉」或「有機蔬果」，並利用冷鏈技術空運至日本。這種農業經營的轉變，最符合下列哪一個概念？", options:["商業性農業與集約度提高","欄牧向游牧轉型","自給性農業的擴張","粗放式農業的推廣"], answer:0, explanation:"此轉型體現出農業「市場指向」與「資金技術密集（集約化）」的特徵。利用高科技設施（溫室）、冷鏈空運面向國際消費市場，為商業性集約農業的典型案例。" },
    { id:"ex_s17", year:2025, subject:"地理", difficulty:"hard", text:"美國矽谷負責研發，臺灣台積電負責晶圓代工，東南亞負責最後的封裝測試。這種跨國的產業結構最能用下列哪一個地理名詞解釋？", options:["垂直整合","空間分工鏈（Spatial Division of Labor）","聚落經濟","同質集聚"], answer:1, explanation:"跨國產業將技術研發（高工資地區）、生產製造（低工資地區）、組裝封裝（勞力密集地區）分工至全球不同地點，以成本最小化為原則，稱為「空間分工鏈」。" },
    { id:"ex_s18", year:2023, subject:"地理", difficulty:"medium", text:"臺灣年降雨量高達 2500 毫米，是全球平均的三倍，卻名列全球缺水國家之一。其最主要的原因不包括下列何者？", options:["降雨季節分配不均（降雨過度集中夏秋）","河流短小流急，雨水快速流失入海","臺灣整體年總降雨量太少"], answer:2, explanation:"臺灣缺水的原因是地形陡峭（河短流急）與降雨時間高度集中（梅雨、颱風季），並非總降雨量不足。臺灣整體年降雨量豐沛，(C)為錯誤敘述，故為「不包括」的正確答案。" },
    { id:"ex_s19", year:2022, subject:"地理", difficulty:"medium", text:"長江中下游地區（如洞庭湖、鄱陽湖）過去因「圍湖造田」導致蓄洪能力大減，近年中國政府推行何種政策來改善此環境問題？", options:["平垸行洪、退田還湖","南水北調工程","砍伐森林擴大耕地","興建更多堤壩強化治水"], answer:0, explanation:"「退田還湖（平垸行洪）」是針對長江中下游過度圍墾導致蓄洪空間縮減的修復策略，以生態保育觀念恢復湖泊濕地面積，提升自然調洪能力。" },
    { id:"ex_s20", year:2024, subject:"地理", difficulty:"medium", text:"印尼近年積極推動「遷都計畫」（從雅加達遷往婆羅洲的東加里曼丹）。導致雅加達不得不遷都的地理環境主因為何？", options:["氣候極度乾燥","地層嚴重下陷與海平面上升","火山爆發頻繁","熱帶雨林過度開墾"], answer:1, explanation:"雅加達因長期過度抽取地下水導致地層下陷，加上全球暖化造成海平面上升，使部分市區已低於海平面，面臨嚴重洪水威脅，是結合時事的地理素養考點。" },
    { id:"ex_s21", year:2026, subject:"地理", difficulty:"medium", text:"美國中部大平原從南向北，依序分布著棉花帶、冬小麥帶、玉米帶、春小麥帶。請問影響「冬小麥」與「春小麥」分布界線的最關鍵因素是？", options:["降雨量的多寡","生育期冬半年的氣溫（緯度高低）","土壤肥沃度","灌溉水源距離"], answer:1, explanation:"緯度較低（南方）冬季較溫和，可種冬小麥（秋播、冬眠、春收）；高緯（北方）冬季嚴寒會凍死幼苗，只能種春小麥（春播秋收）。故關鍵因素為緯度所影響的冬季氣溫。" },
    { id:"ex_s22", year:2025, subject:"地理", difficulty:"medium", text:"西亞（如敘利亞）與北非的難民冒險渡過地中海前往德國。若以「人口推拉理論」分析，敘利亞的「內戰與戰亂」屬於下列何者？", options:["推力（Push factor）","拉力（Pull factor）","中介障礙","人口自然增長"], answer:0, explanation:"推拉理論：家鄉負面因素（戰亂、貧窮、環境惡化）為推力，促使人口外移；目的地正面因素（高薪、安全、自由）為拉力。地中海險惡海域則為中介障礙。" },
    { id:"ex_s23", year:2024, subject:"地理", difficulty:"medium", text:"隨著北極冰帽加速融化，「北極航線」將可常態通航。這對下列哪一組地區之間的貨運航程縮短最為顯著？", options:["亞洲東部（如中日韓）與歐洲西北部","澳洲與南美洲","非洲與南極洲","北美洲東岸與西非"], answer:0, explanation:"傳統航線從亞洲到歐洲須繞道馬六甲海峽與蘇伊士運河，北極航線可縮短亞歐之間約 40% 的航程，對東北亞（中日韓）與歐洲西北部的貿易往來節省最顯著。" },

    // ===== 歷史 =====
    { id:"ex_s24", year:2023, subject:"歷史", difficulty:"medium", text:"17世紀某政權治臺時期，為控制原住民各社，實施「地方集會」（Landdag）制度，要求各社頭目向長官順服納貢。請問這是哪一個政權？", options:["荷蘭東印度公司","鄭氏政權","大清帝國","日本總督府"], answer:0, explanation:"荷蘭時期的「地方會議（Landdag）」是核心考點，藉由集會讓各原住民社頭目宣誓效忠並納貢，以低成本間接統治。大考極愛考不同政權下原住民的統治模式變遷。" },
    { id:"ex_s25", year:2022, subject:"歷史", difficulty:"medium", text:"臺灣在19世紀下半葉開港通商後，哪一項大宗商品的出口帶動了「茶金」熱潮，並使臺灣的經濟與政治重心逐漸「由南向北」轉移？", options:["蔗糖","烏龍茶與樟腦","鹿皮","稻米"], answer:1, explanation:"開港通商（1860年代）後，茶與樟腦的產地在中北部山區，其出口興起打破了傳統清代以府城（台南）為中心的格局，促成北臺灣（大稻埕、艋舺）繁榮，帶動政經重心北移。" },
    { id:"ex_s26", year:2024, subject:"歷史", difficulty:"medium", text:"1920年代，林獻堂、蔣渭水等人積極推動「臺灣議會設置請願運動」，並成立臺灣文化協會。這波社會運動興起的主要國際背景為何？", options:["第一次世界大戰後的「民族自決」思潮","冷戰時期的反共圍堵政策","二戰後的去殖民化浪潮","朝鮮戰爭爆發引發的區域動盪"], answer:0, explanation:"一戰後美國總統威爾遜提出「民族自決」原則，啟發全球殖民地人民的政治覺醒。臺灣知識分子因此受到鼓舞，推動議會請願、文化啟蒙等自治運動。" },
    { id:"ex_s27", year:2025, subject:"歷史", difficulty:"medium", text:"1950年代，臺灣在戒嚴體制下，地方選舉仍能照常舉行。這種「地方層級的選舉」之所以被允許，最主要的目的是什麼？", options:["迎合美國盟友，建立「自由中國」的民主櫥窗形象","全面實施西方憲政民主","確保中央民意代表能充分反映民意","推動地方自治以強化國家認同"], answer:0, explanation:"冷戰時期國民政府依賴美援，為了向美國及西方世界證明其與共黨中國的差異，維持了縣市長、省議員等基層地方選舉，形成「自由中國」的民主窗口形象。" },
    { id:"ex_s28", year:2022, subject:"歷史", difficulty:"medium", text:"漢、唐、明等朝代與周邊政權（如朝鮮、琉球、越南）交往時，通常建立在何種外交關係架構下？", options:["國際法尊重的平等外交","宗藩關係與朝貢貿易體制","同盟互助的軍事條約體系","殖民地經濟剝削體制"], answer:1, explanation:"東亞傳統「朝貢體制」中，周邊國家接受中原皇帝「冊封」（名義上的君臣關係），以此換取合法貿易權利與政治承認，形成以中國為核心的天下秩序。" },
    { id:"ex_s29", year:2024, subject:"歷史", difficulty:"medium", text:"中國古代某制度自隋唐確立後，打破了世族對政治權力的壟斷，使平民有機會透過苦讀翻身。請問這是哪一項制度？", options:["九品官人法","科舉制度","察舉制","封建制"], answer:1, explanation:"魏晉南北朝的九品官人法導致「上品無寒門，下品無士族」。隋唐確立科舉制度後，以筆試成績取才，極大促進了社會階層的縱向流動，形成獨特的士紳階級。" },
    { id:"ex_s30", year:2023, subject:"歷史", difficulty:"medium", text:"19世紀中葉後，大清帝國推行了自強運動（洋務運動），而日本則實施了哪一項改革，使其迅速躍升為亞洲新興強國？", options:["明治維新","大化革新","戊戌變法","光緒新政"], answer:0, explanation:"明治維新（1868年起）是日本全面性的西化改革，涵蓋政體（廢藩置縣）、軍事、教育、經濟，與大清「中體西用（只改器物）」的洋務運動形成強烈對比，成效截然不同。" },
    { id:"ex_s31", year:2026, subject:"歷史", difficulty:"medium", text:"1950年爆發的哪一場戰爭，不僅確立了朝鮮半島的分裂局面，更促使美國將臺灣納入亞太防禦體系（派遣第七艦隊協防臺灣海峽）？", options:["國共內戰","韓戰","越戰","中日戰爭"], answer:1, explanation:"韓戰（1950-1953）是冷戰在東亞全面爆發的轉折點。美國擔憂共產主義骨牌效應，將原本已放棄的臺灣重新納入西太平洋防禦鏈，改變了東亞政治版圖。" },
    { id:"ex_s32", year:2022, subject:"歷史", difficulty:"medium", text:"古雅典的「公民大會」與古羅馬的「成文法（如十二銅表法）」，分別奠定了現代西方政治的哪兩大核心基石？", options:["民主與法治","神權與王權","資本主義與社會主義","自由主義與保守主義"], answer:0, explanation:"古希臘雅典是直接民主的發源地，公民大會奠定民主基礎；古羅馬的十二銅表法與羅馬法體系建立了法治的典範，兩者共同構成現代西方政治文明的核心。" },
    { id:"ex_s33", year:2024, subject:"歷史", difficulty:"medium", text:"16世紀由馬丁路德、加爾文等人發起的運動，動搖了羅馬天主教會的絕對權威，並強調「因信稱義」。請問這場運動稱為什麼？", options:["文藝復興","宗教改革","啟蒙運動","科學革命"], answer:1, explanation:"宗教改革促成基督新教（Protestantism）的誕生，打破中世紀天主教會的精神壟斷，並引發歐洲一系列宗教戰爭與後續的思想解放。「因信稱義」是馬丁路德神學的核心論點。" },
    { id:"ex_s34", year:2023, subject:"歷史", difficulty:"medium", text:"15-16世紀哥倫布到達美洲後，引發了全球性的「哥倫布大交換」。下列哪一組作物原生自美洲，引進歐亞大陸後極大緩解了糧食危機？", options:["馬鈴薯、番薯、玉米","水稻、小麥、大麥","棉花、茶葉、菸草","甘蔗、橄欖、葡萄"], answer:0, explanation:"馬鈴薯、番薯、玉米均為美洲原生作物，具耐旱高產的特性，傳入歐亞大陸後成為基層平民主食，直接促成了17-18世紀全球人口的劇烈成長。" },
    { id:"ex_s35", year:2025, subject:"歷史", difficulty:"medium", text:"18世紀的啟蒙思想家中，孟德斯鳩提出的哪一項政治學說，成為現代民主國家憲法制衡的典範？", options:["天賦人權","三權分立","主權在民","社會契約"], answer:1, explanation:"洛克主「天賦人權」；孟德斯鳩主「三權分立（行政、立法、司法互相抗衡）」；盧梭主「主權在民與社會契約」。三者均為大考常考的啟蒙思想核心，需能區分各自代表人物。" },
    { id:"ex_s36", year:2022, subject:"歷史", difficulty:"medium", text:"18世紀末英國爆發工業革命後，在社會結構上催生了哪兩個互相對立的新興階級？", options:["貴族與農奴","資產階級（資本家）與無產階級（勞工）","地主與佃農","神職人員與平民"], answer:1, explanation:"工業革命帶來機器大生產與都市化，形成掌握生產資料的資產階級（布爾喬亞）與出賣勞動力的無產階級（普羅大眾），兩者對立促成19世紀勞工運動與馬克思共產主義思潮。" },
    { id:"ex_s37", year:2026, subject:"歷史", difficulty:"medium", text:"19世紀末，歐洲列強因爭奪海外殖民地、推行軍備競賽，形成「三國同盟」與「三國協約」兩大軍事集團。這種國際緊張局勢最後因哪一區域的「火藥庫」爆炸而引發了一戰？", options:["巴爾干半島","伊比利半島","義大利半島","斯堪地那維亞半島"], answer:0, explanation:"巴爾干半島因民族成分複雜、地緣戰略位置重要且列強勢力介入，素有「歐洲火藥庫」之稱。1914年塞拉熱窩事件（奧匈皇儲遇刺）在此點燃一戰導火線。" },
    { id:"ex_s38", year:2024, subject:"歷史", difficulty:"medium", text:"第二次世界大戰結束後，下列哪一個組織的建立，屬於美國在歐洲對抗共產主義擴張的「軍事集團」？", options:["北大西洋公約組織（NATO）","華沙公約組織（Warsaw Pact）","歐洲共同體（EC）","馬歇爾計畫"], answer:0, explanation:"冷戰軍事對峙：美國與西歐盟國建立北約（NATO，1949）；蘇聯與東歐鐵幕國家則建立華約（Warsaw Pact，1955）以為反制。兩大集團對峙是冷戰格局的核心。" },

    // ===== 公民 =====
    { id:"ex_s39", year:2022, subject:"公民", difficulty:"medium", text:"當青少年在決定未來大學科系時，會高度在意父母、師長以及死黨（重要他人）對自己的看法。這最符合米德所說社會化過程中的哪一個階段？", options:["準備階段","模仿階段","遊戲階段","團體遊戲（競賽）階段"], answer:3, explanation:"米德社會化四階段中，「團體遊戲（競賽）階段」個體能同時考量多個他人觀點，並內化「概括化他人（Generalized others）」的規範，高度在意社會評價，符合青少年的發展特徵。" },
    { id:"ex_s40", year:2023, subject:"公民", difficulty:"medium", text:"過去某些西方古典音樂被視為「高雅文化」，而本土民間歌仔戲被貼上「通俗/低俗」的標籤。這種現象在社會學上最適合用哪一個概念來批評？", options:["文化位階（Cultural Hierarchy）","文化混搭","文化資產","文化帝國主義"], answer:0, explanation:"「文化位階」指社會強勢群體將特定文化賦予較高地位，進而貶低其他文化。新課綱強調以「文化相對論」視角看待各文化的平等價值，反對文化位階所造成的不平等。" },
    { id:"ex_s41", year:2024, subject:"公民", difficulty:"medium", text:"調查發現，某些高階主管職位存在「玻璃天花板（Glass Ceiling）」現象，使女性或少數族群在職場晉升時面臨隱形阻礙。這屬於何種形式的不平等？", options:["階級間的自由流動","結構性限制與歧視","資本市場的自然淘汰","個人能力的自然差異"], answer:1, explanation:"「玻璃天花板」是社會階層化中的結構性歧視，指制度、組織文化或社會偏見對特定群體（女性、少數族群）造成的隱形晉升障礙，非個人能力問題，而是制度問題。" },
    { id:"ex_s42", year:2023, subject:"公民", difficulty:"medium", text:"某國的行政首長（總理）由國會多數黨領袖出任，當國會通過對總理的不信任案時，總理亦可呈請國家元首解散國會。請問該國屬於何種體制？", options:["總統制","內閣制","半總統制（雙首長制）","君主專制"], answer:1, explanation:"內閣制的核心特徵：行政與立法合一（總理由國會多數產生）、具備「不信任案（倒閣）」與「解散國會」的相互制衡機制。英國、日本為典型範例；臺灣屬半總統制。" },
    { id:"ex_s43", year:2025, subject:"公民", difficulty:"medium", text:"臺灣立法委員選舉採用「單一選區兩票制」，在「單一選區」中，最容易產生何種政黨體態？", options:["一黨專政","兩黨制（多黨趨向兩黨）","穩固的多黨體制","比例代表制下的多黨均衡"], answer:1, explanation:"依杜瓦傑定律（Duverger's law），單一選區相對多數決因「票票不等值」不利小黨生存，容易催生兩黨競爭格局；而比例代表制則有助於小黨獲得席次，利於多黨制。" },
    { id:"ex_s44", year:2022, subject:"公民", difficulty:"medium", text:"關於我國《公民投票法》規定的「全國性公民投票」，下列哪一項敘述正確？", options:["投票年齡門檻為年滿 18 歲","公投可以針對預算、租稅、薪俸事項進行提案","公投通過門檻為有效票數過半且達選舉人總數 1/4","公投案一旦通過，永久有效不得再次複決"], answer:0, explanation:"公投法明定投票年齡為 18 歲。重要限制：預算、租稅、薪俸及人事事項「不得」作為公投提案；通過門檻為有效同意票超過有效投票數的 1/2，且不低於選舉人總數的 1/4。" },
    { id:"ex_s45", year:2026, subject:"公民", difficulty:"medium", text:"世界衛生組織（WHO）或世界貿易組織（WTO），這類由主權國家組成的國際機構，在國際法上屬於何種類型？", options:["政府間國際組織（IGO）","非政府組織（NGO）","跨國企業（MNC）","區域經濟整合體"], answer:0, explanation:"由各國政府代表加入並以主權國家為成員的國際組織稱為 IGO（Intergovernmental Organization）；由民間社會自發組成（如紅十字會、國際特赦組織）的則為 NGO。" },
    { id:"ex_s46", year:2022, subject:"公民", difficulty:"medium", text:"大明因闖紅燈被警察開了一張罰單，他認為處分不公。若大明想要進行「行政救濟」，他的第一步程序通常是什麼？", options:["向法院提起民事訴訟","向原處分機關的上一級機關提起「訴願」","直接向行政法院提起行政訴訟","向監察院申請彈劾"], answer:1, explanation:"行政救濟路線：不服行政機關處分 → 提起訴願（向上一級機關）→ 仍不服 → 提起行政訴訟（向行政法院）。訴願為行政訴訟的前置程序，不可略過直接提告。" },
    { id:"ex_s47", year:2023, subject:"公民", difficulty:"medium", text:"依據現行民法規定，年滿 18 歲為成年。若一名 16 歲的高中生（限制行為能力人），在未經父母（法定代理人）同意下，自行簽約購買一部新機車。請問該契約效力為何？", options:["完全有效","完全無效","效力未定","自動撤銷"], answer:2, explanation:"限制行為能力人（7歲以上未滿18歲）所訂之契約（非日常必需或純獲利益者），須經法定代理人承認方生效，在承認前屬於「效力未定」；若代理人拒絕承認則確定無效。" },
    { id:"ex_s48", year:2025, subject:"公民", difficulty:"medium", text:"小華走在路上突然遭到惡犬攻擊，為了保護自己，他隨手拿起路邊商家的雨傘將惡犬打傷。小華的行為最可能主張何種「阻卻違法事由」而不受處罰？", options:["正當防衛","緊急避難","依法令之行為","被害人承諾"], answer:1, explanation:"正當防衛是對「不法侵害人」的防衛；緊急避難是面對「非人為不法侵害（如動物攻擊、自然災害）」引起的緊急危難，為了保護較大利益（生命）而不得不損害較小利益（雨傘），適用緊急避難。" },
    { id:"ex_s49", year:2026, subject:"公民", difficulty:"medium", text:"根據現行法律，若 10 歲兒童與 14 歲少年分別觸犯刑罰法律，司法機關應如何處理？", options:["兩者皆移送刑事法庭判刑","10歲兒童不適用少事法（回歸教育社政體系）；14歲少年則移送少年法庭處理","兩者皆適用《少年事件處理法》移送少年法庭","兩者皆不負任何法律責任"], answer:1, explanation:"現行法制：7歲以上未滿12歲之兒童觸法，除罪化，全面由教育與社政輔導；12歲以上未滿18歲則適用《少年事件處理法》，由少年法庭處理。14歲符合後者，適用少事法。" },
    { id:"ex_s50", year:2023, subject:"公民", difficulty:"medium", text:"小美烘焙一條麵包的機會成本是 2 個蛋糕，小明烘焙一條麵包的機會成本是 3 個蛋糕。根據「比較利益原則」，兩者應如何分工？", options:["小美負責烘焙麵包，小明負責製作蛋糕","小明負責烘焙麵包，小美負責製作蛋糕","兩人共同製作麵包，合作效率最高","由能力較強者同時生產兩者"], answer:0, explanation:"比較利益原則：機會成本愈低者具備比較利益。小美做麵包的機會成本（2個蛋糕）低於小明（3個蛋糕），故小美專精麵包，小明專精蛋糕，各自生產比較利益所在的商品。" },
    { id:"ex_s51", year:2022, subject:"公民", difficulty:"medium", text:"當政府為了照顧基層消費者，實施「價格上限（Price Ceiling）」（如：限制口罩或雞蛋最高售價低於市場均衡價格）時，市場會出現何種現象？", options:["供過於求（生產過剩）","供不應求（產生短缺、排隊或黑市）","市場自動達到新的均衡","供需維持不變"], answer:1, explanation:"價格上限低於均衡價格：廠商因利潤下降而減少供給，消費者因售價偏低而增加需求，導致「供不應求（短缺）」，嚴重時出現排隊現象或黑市交易（以高於管制價的非法方式流通）。" },
    { id:"ex_s52", year:2024, subject:"公民", difficulty:"medium", text:"工廠排放廢氣造成附近居民健康受損，這在經濟學上稱為「外部成本（外部不經濟）」。政府可以透過下列哪一種方式將其「內部化」？", options:["給予工廠課稅（如徵收碳費、課徵污染稅）","給予工廠無上限的財政補貼","鼓勵企業自願減排而不介入","降低工廠的生產稅以換取減排承諾"], answer:0, explanation:"負外部性內部化：對產生外部成本（污染）的廠商課徵「庇古稅（Pigouvian Tax）」（如碳費、污染稅），使廠商將社會成本納入生產決策，促使其減少污染至社會最適水準。" },
    { id:"ex_s53", year:2025, subject:"公民", difficulty:"medium", text:"下列哪一項活動，會被列入臺灣當年度的 GDP 計算之中？", options:["媽媽在家裡做家務照顧小孩的勞務價值","外籍勞工在臺灣工廠工作所創造的生產價值","購買過戶二手中古車的交易總車價","股票在市場上漲後所增加的帳面資產價值"], answer:1, explanation:"GDP 定義為「當期、境內、最終財貨與服務的市場價值總和」。(A)家務無市場交易不計；(C)二手車非當期生產不計（仲介費計入）；(D)股票為金融資產非產出。外籍勞工在臺灣境內當期生產，故計入 GDP。" },
    { id:"ex_s54", year:2026, subject:"公民", difficulty:"medium", text:"政府為因應重大傳染病，強制規定確診者必須集中隔離。此舉限制了公民的「居住遷徙自由」，根據憲法第23條，政府限制人民基本權利必須符合哪些核心原則？", options:["公益原則、法律保留原則、比例原則（手段目的相稱）","緊急命令原則、行政裁量原則、效率原則","民意調查原則、行政效率原則、政黨共識原則","司法核准原則、選舉授權原則、國會多數決原則"], answer:0, explanation:"依憲法第23條，限制人民自由須符合：①防止妨礙他人自由、②避免緊急危難、③維持社會秩序、④增進公共利益等目的（公益原則），且必須以「法律」為之（法律保留），且限制手段與目的相稱（比例原則）。" },
  ]
};

// 取得指定科目題目（可依難度篩選）
function getQuestions(subject, difficulty = "all", count = 10) {
  let pool = QUESTION_BANK[subject] || [];
  if (difficulty !== "all") {
    pool = pool.filter(q => q.difficulty === difficulty);
  }
  const shuffled = [...pool].sort(() => Math.random() - 0.5);
  return shuffled.slice(0, Math.min(count, shuffled.length));
}

// 取得考古題（可依年份、科目篩選）
function getExamQuestions(year = "all", subject = "all", difficulty = "all") {
  let pool = QUESTION_BANK["exam_gaokao"] || [];
  if (year !== "all")       pool = pool.filter(q => q.year === parseInt(year));
  if (subject !== "all")    pool = pool.filter(q => q.subject === subject);
  if (difficulty !== "all") pool = pool.filter(q => q.difficulty === difficulty);
  return pool;
}
